(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-efficient-audio-visual-event-recogni-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-1\">一 · 一个夜间值守的摄像头：为什么旧栈撑不住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-2\">二 · 旧方案的三笔账：显存、矩阵乘、对齐精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-3\">三 · 静态量化为啥在这个负载上失灵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-4\">四 · 容量这一侧：蒸馏不是可选项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-5\">五 · 精度保护：融合层必须与编码器层区别对待</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-6\">六 · 在线事件识别服务里，跨模态融合层为何先被压垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-7\">七 · 时间窗如何决定 token 长度分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-8\">八 · 并发与批大小：动态定标把批变成数值变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-9\">九 · SLO 由窗长与聚合方式共同定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-10\">十 · 长尾：三类来源与各自的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-11\">十一 · 负载塑造方案，方案反过来限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-12\">十二 · 窗口形态如何反过来定义量化边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-13\">十三 · 跨注意力融合的算子拆解与量化落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-14\">十四 · 数据类型谱系：从 FP16/BF16 到 FP8 与 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-15\">十五 · 累加精度与误差传导路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-16\">十六 · Blackwell 第五代 Tensor Core 与 tcgen05 的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-17\">十七 · 精度保护与 kernel 融合的工程取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-18\">十八 · 显存账本的四个户头：权重、激活、KV、工作区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-19\">十九 · 分页与复用：把 KV 从连续大块改成可回收的页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-20\">二十 · 带宽瓶颈的位置：INT8 省的是字节，不是访存次数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-21\">二十一 · 卸载与放置：哪些张量可以离开 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-22\">二十二 · 可复算的显存预算：一张按配置代入的表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-23\">二十三 · 带宽与容量的联立判断：瓶颈落在哪一侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-24\">二十四 · 从窗口到达模式反推调度粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-25\">二十五 · Chunked prefill 在跨模态融合层的切分点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-26\">二十六 · 优先级与抢占：分类分数漂移作为抢占信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-27\">二十七 · 分离式预填/解码与跨注意力高精度段的落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-28\">二十八 · 尾延迟的三个来源与压制顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-29\">二十九 · 批调度与量化保护的耦合判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-30\">三十 · 调度边界：动态定标与跨注意力保护如何约束批处理策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-31\">三十一 · 切分维度：这套融合网络到底该按什么切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内通信的物理底座</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-33\">三十三 · All-Reduce 与 All-to-All：两种集合通信的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-34\">三十四 · NIXL 传输：分离式部署下的状态搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-35\">三十五 · 通信何时成为瓶颈：三个可判定的信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-36\">三十六 · 与量化策略的耦合：并行选择反过来约束数值方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-37\">三十七 · 融合层量化与并行切分的错位：边界、失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-38\">三十八 · 精度塌陷：从分数漂移到对齐失配的定位链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-39\">三十九 · OOM 与激活峰值：动态定标的显存副作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-40\">四十 · 批抖动：动态定标与批组成的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-41\">四十一 · 尾延迟：窗口长度与跨注意力复杂度的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-42\">四十二 · 静默降级：没有报错的精度损失最危险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-43\">四十三 · 动态定标的分布陷阱与精度塌陷的可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-44\">四十四 · 基准表的三个空位：模型、硬件、负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-45\">四十五 · batch 与并发：动态定标的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-46\">四十六 · 指标口径：TTFT、TPOT 与吞吐在事件识别里的变形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-47\">四十七 · 哪些提升不可比：四类跨表陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-48\">四十八 · 读表顺序：从校准样本到分数漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-49\">四十九 · 迁移到别的融合结构：先看跨注意力是不是瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-50\">五十 · 蒸馏环节的迁移条件：教师软标签是否携带对齐信息</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-51\">五十一 · 动态 INT8 的适用边界：batch 分布与长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-52\">五十二 · 规模上限：这套方案在哪里触顶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-53\">五十三 · 不适用的场景与替代路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-efficient-audio-visual-event-recogni-2026-sec-54\">五十四 · 迁移边界：什么能搬、什么必须重算</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:543px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 543.2 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">音频与视觉输入分别经各自编码器前端提取帧级特征，形成两路 token …</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">两路 token 进入跨注意力融合层，视觉 token 作为 quer…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">融合后的表示经前馈层与分类头输出事件类别分数。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">部署时线性层权重以 INT8 存储，激活在前向时按当前 batch 动…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">跨注意力打分与 softmax 在较高精度累加，避免量化误差破坏模态对…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出类别分数并按时间窗聚合，形成事件识别结果。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-1\">一 · 一个夜间值守的摄像头：为什么旧栈撑不住</h3>\n<p>设想一台部署在园区出入口的边缘节点，承担音频视觉事件识别：同一时间窗内，画面里有人摔倒、同时传来撞击声与呼喊，系统要在窗口结束后的极短时间内给出事件类别，供上层联动门禁与告警。请求以单窗或小批形式到达，窗口长度可变，音频帧序列与视频帧序列的 token 长度随窗口伸缩。这类负载的工程特征很明确：批小、到达不规则、端到端延迟被窗口长度与帧采样率共同约束，而显存预算被同一块卡上的其他服务切走一部分。</p>\n<p>在这篇论文之前，主流推理栈对这种跨模态融合网络的处理方式相当“朴素”：把训练好的混合跨注意力网络原样导出，权重以 FP16/BF16 存放，激活不做任何压缩，跨注意力融合层与两路编码器一视同仁地走同一条高精度路径。工程上并非没有压缩手段——静态 INT8 量化、通道剪枝、早期拼接式的轻量融合都在工具箱里——但它们各自与这个场景的形态错位。静态量化要求激活动态范围在离线校准阶段就被固定下来，而这里的音频与视觉 token 长度逐窗变化，激活分布随窗口内容漂移；剪枝会破坏跨注意力层的通道对齐关系；把融合退化成早期拼接则直接放弃模态对齐能力。于是旧栈的默认选择就是“不压”，代价全部落在显存与时延上。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-2\">二 · 旧方案的三笔账：显存、矩阵乘、对齐精度</h3>\n<p>第一笔账是激活显存。跨注意力融合网络的参数量与激活占用偏高，这一点在材料中被明确点出。融合层的中间表示规模与两路 token 长度成正比：视觉 token 作 query、音频 token 作 key/value，打分矩阵的尺寸是两路长度的乘积量级。窗口拉长时，这个矩阵与随后的 softmax、加权求和缓冲一起膨胀，而边缘档位的显存本就紧张。批大小因此被压到极小，吞吐随之被锁死——不是算力不够，是放不下。</p>\n<p>第二笔账是矩阵乘代价。线性层与跨注意力投影全部走 FP16 时，权重带宽与 Tensor Core 吞吐都按高精度档位结算。对单窗请求而言，这类网络的算力需求并不夸张，但权重读取的字节数决定了单次前向的下限延迟；在批很小的情况下，矩阵乘是典型的带宽受限而非算力受限，精度每降一档，权重流量就近似减半，这是量化最直接的收益来源。</p>\n<p>第三笔账最容易被忽视：对齐精度。跨注意力的打分矩阵经 softmax 后形成模态间的对齐权重，这些权重本身数值动态范围大、长尾分布明显。若把打分与 softmax 一并塞进低精度整数路径，量化噪声会直接淹没小权重项，对齐关系被扭曲，误差沿前馈层传导到分类头。旧栈因为不敢碰这一层，索性整网保持高精度，用显存和带宽换对齐稳定性——这正是“非改不可”的根源：不是没有压缩技术，而是没有一种压缩技术能同时照顾容量、动态范围与对齐算子。</p>\n<div class=\"formula\">$$s_x=\\frac{127}{\\max|x|},\\qquad \\hat{y}=\\mathrm{softmax}\\left(\\frac{(Q_v W_q)\\,(K_a W_k)^{\\top}}{\\sqrt{d}}\\right)V_a W_v$$</div>\n<p>上式右侧是融合算子的形状，左侧是动态定标的缩放因子。旧栈把 $W_q,W_k,W_v$ 留在 FP16，等于放弃了 $s_x$ 这条路径带来的全部带宽收益；而若贸然对打分矩阵套用同一个 $s_x$，$\\max|x|$ 由长尾大值主导，小对齐权重被压到整数格点以下，精度损失不可控。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-3\">三 · 静态量化为啥在这个负载上失灵</h3>\n<p>静态 INT8 的工程假设是：校准集上统计出的每层激活范围，能代表线上分布。这个假设在固定输入形状的视觉分类里大致成立，在这里不成立。音频与视觉两路 token 长度随窗口变化，融合层激活的张量形状逐请求不同；窗口内容从静默走廊切换到嘈杂路口，激活的最大绝对值可以跨越数量级。离线定下的缩放因子要么过松（浪费整数位宽、等效精度下降），要么过紧（大量激活被截断）。材料把这一点归为“静态量化难以适配动态范围”，本质是校准分布与线上分布的系统性错配。</p>\n<p>更麻烦的是“不重训”约束。线上服务不可能为每一次分布漂移回炉重训，量化方案必须能在已训练好的网络上一插即用。静态量化在分布漂移时需要重新校准甚至量化感知训练，工程闭环太长；而这篇论文选择的动态 INT8 把定标搬到前向现场——权重离线转整数存储，激活在每个 batch 内按实际最大绝对值现算 $s_x$ 再量化，矩阵乘在 INT8 上执行并以较高精度累加。校准阶段只需少量样本统计各层动态范围，蒸馏完成后学生网络不再重训。代价是每次前向多一次归约求最大值的开销，收益是免去重训闭环、并对形状与内容漂移天然免疫。</p>\n<ul>\n<li>机制：权重离线 INT8，激活按 batch 内 $\\max|x|$ 现场定标；跨注意力打分矩阵与 softmax 保留较高精度累加。</li>\n<li>代价：动态定标引入逐层归约，单请求延迟增加一个小的固定项；换来权重流量近似减半与激活显存按 4 倍压缩的存储口径。</li>\n<li>例子：一个窗口内视觉 token 数翻倍，静态方案的缩放因子失配，动态方案在同一 batch 内重新算出 $s_x$，打分矩阵仍以高精度累加，对齐分数不被量化噪声淹没。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-4\">四 · 容量这一侧：蒸馏不是可选项</h3>\n<p>只做量化解决不了参数量问题。融合网络的容量偏高，权重即使压到 INT8，层数与通道数仍在，激活显存的形状项也没变。论文的路径是先蒸馏再量化：教师网络两路分支各自编码后进入跨注意力融合层，学生网络缩小通道与层数，但保留跨注意力结构而非退化为早期拼接——这一点是工程判断的关键，因为模态对齐能力恰恰住在融合层里，砍掉它等于把精度问题从量化转移到了结构。</p>\n<p>蒸馏损失由三项组成：学生与教师软标签的 KL 散度、学生与真实标签的交叉熵、跨注意力层中间特征的均方误差。第三项是把对齐行为本身作为监督信号，而不只是监督输出分布；软标签项则把教师的类间相对关系迁移过来，弥补学生容量缩小后对长尾事件的判别力损失。材料未给出各项权重系数与蒸馏轮数，因此这里只能定性：三项的配比决定了学生网络在量化前的“余量”，余量越足，后续 INT8 引入的噪声越不容易把分类分数推过决策边界。</p>\n<p>从系统代价看，蒸馏是一次性离线成本，换来的是部署期的双重收益：学生网络的权重与激活规模下降，动态 INT8 再把权重存储与矩阵乘流量压一档。对边缘节点而言，这意味着批大小可以从“勉强放下一个窗口”提升到能容纳小批并发，吞吐的改善来自显存释放而非算力增加。材料未给出硬件档位与实测延迟，因此无法核算在 B200 或 GB200 NVL72 上的具体收益；但机制上可以判断，这条路径的瓶颈从来不是 Tensor Core 峰值，而是权重带宽与激活占用。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-5\">五 · 精度保护：融合层必须与编码器层区别对待</h3>\n<p>这篇论文在量化策略上最值得记住的一条工程选择，是把跨注意力打分矩阵与 softmax 排除在全 INT8 之外，保留较高精度累加。理由在第二节已经给出：对齐权重是长尾分布，量化噪声对小权重项的相对误差最大，而分类输出恰恰依赖这些弱对齐项的累积。若把整网一压到底，压缩收益被高估，分类分数漂移会在长尾样本上集中出现——这正是材料列出的失败模式之一。</p>\n<p>由此引出一个可操作的部署判断：融合层的量化粒度应当比编码器层更保守。编码器前端提取帧级特征，激活分布相对平稳，动态 INT8 的收益可以直接兑现；融合层则要保留打分与 softmax 的高精度路径，只对线性投影与权重做整数化。这种“分层差别对待”的策略，使得压缩比不是全局统一的一个数，而是按算子角色分配的预算。材料未给出量化后精度损失幅度与跨注意力层对量化的敏感度，也未与静态 INT8、FP8、NVFP4 做对比，因此方案选择依据在材料中不完整；但从机制上看，动态定标加算子级精度保护的组合，是“不重训”约束下唯一能同时压容量与保对齐的路径。</p>\n<table class=\"mini\"><thead><tr><th>算子</th><th>旧栈做法</th><th>论文做法</th><th>系统代价</th></tr></thead><tbody><tr><td>线性层权重</td><td>FP16 常驻</td><td>离线 INT8 存储</td><td>权重流量近似减半，单请求下限延迟下降</td></tr><tr><td>激活</td><td>FP16，无压缩</td><td>按 batch 动态定标后 INT8</td><td>逐层归约开销；激活显存按整数口径压缩</td></tr><tr><td>跨注意力打分 / softmax</td><td>FP16</td><td>保留较高精度累加</td><td>放弃该算子全部整数收益，换取对齐稳定</td></tr><tr><td>融合结构</td><td>原样保留</td><td>学生网络保留跨注意力</td><td>蒸馏一次性成本，部署期容量下降</td></tr></tbody></table>\n<p>把这张表放回开场的夜间值守场景：一个窗口请求到达，两路编码器出 token，融合层在动态定标后的整数矩阵乘上完成对齐，打分与 softmax 走保精度路径，分类头给出事件分数。旧栈在这个链路上每一环都按高精度结算，显存与带宽双重吃紧；新路径把可压的部分压到位，把不能压的部分明确保护起来。真正的工程分歧不在“要不要量化”，而在“哪些算子允许被量化噪声触碰”——这条边界划在哪里，决定了压缩收益能否兑现而不以对齐精度为代价。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-6\">六 · 在线事件识别服务里，跨模态融合层为何先被压垮</h3>\n<p>设想一个持续运行的音视频事件识别服务：摄像头与麦克风按固定时间窗切片，每个请求携带一段音频帧序列与一段视频帧序列，两路 token 长度随窗口长度浮动。旧栈的主流做法是把教师级混合跨注意力网络原样部署——音频分支与视觉分支各自编码后进入跨注意力融合层，视觉 token 作 query、音频 token 作 key/value 对齐，再经前馈与分类头出分。问题不在单次前向的算力峰值，而在融合层的激活显存与矩阵乘代价随窗口线性上涨：跨注意力打分矩阵尺寸正比于两路 token 长度之积，softmax 前后各需一份中间量驻留，权重与激活同时挤占显存，批大小被迫压到很小，吞吐被批调度卡死。更麻烦的是两路 token 长度动态变化，静态量化按固定缩放因子定标，长窗口下激活动态范围溢出、短窗口下分辨率浪费，量化误差直接传导到对齐分数。</p>\n<p>量化路径上的代价可以用缩放因子公式看清：<span class=\"formula\">$$s_x=\\frac{127}{\\max|x|},\\quad \\hat{y}=\\mathrm{softmax}\\left(\\frac{(Q_vW_q)(K_aW_k)^{\\top}}{\\sqrt{d}}\\right)V_aW_v$$</span> 权重离线转 INT8 只解决存储带宽，激活若沿用静态定标，则 <span class=\"formula\">$$\\max|x|$$</span> 由校准集一次性固定，线上遇到长尾样本时实际最大值超出校准范围，截断误差在跨注意力打分上被 softmax 放大。旧方案要么放弃量化、保留 FP16 融合层，显存与矩阵乘代价居高不下；要么全链路 INT8 一刀切，模态对齐精度崩坏。两者都要求重训或大规模重校准，部署前工程成本高，服务侧无法在不中断的情况下迭代。</p>\n<p>该论文的边界正在这里：它把压缩拆成两级——蒸馏先把教师容量迁到保留跨注意力结构的轻量学生，量化再对学生做动态 INT8，权重离线、激活按 batch 内实际最大绝对值现场定标，而跨注意力打分与 softmax 明确保留较高精度累加。这条路径的失效条件同样清晰：动态定标对 batch 内激活分布敏感，长尾样本拉低缩放因子精度，分类分数漂移；材料未给出硬件档位与实测延迟，因此在 B200/GB200 NVL72 上的吞吐收益无法从机制直接外推；论文也未与静态 INT8、FP8、NVFP4 对比，方案选择依据不完整。工程判断上，融合层必须与编码器层区别对待——把动态 INT8 当成全链路量化会高估压缩收益，而忽略打分矩阵的高精度保护则会让对齐误差直接吃掉分类精度。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-7\">七 · 时间窗如何决定 token 长度分布</h3>\n<p>音频视觉事件识别的请求单位不是一条“句子”，而是一个对齐的时间窗：同一窗内的音频帧序列与视频帧序列各自编码成两路 token。窗长一旦变化，两路 token 长度就同时变化，且变化比例并不一致——音频侧受采样率与帧移支配，视觉侧受帧率与 patch 划分支配。这意味着本方案的输入长度分布不是单一标量，而是一个二维联合分布 (L_a, L_v)，跨注意力打分矩阵的规模正比于 L_v × L_a。</p>\n<p>跨注意力算子的代价可以写成显式的形状函数。设视觉 token 为 query、音频 token 为 key/value，融合层单头打分的乘加量约为：</p>\n<div class=\"formula\">$$C_{\\text{fuse}} \\approx 2\\,L_v L_a d + 2\\,L_v d^2,\\qquad M_{\\text{score}} = 4\\,L_v L_a\\ \\text{(bytes, FP32)}$$</div>\n<p>第一项随窗长平方增长，第二项随窗长线性增长。工程含义很直接：短窗请求被投影与 FFN 支配，长窗请求被打分矩阵支配。因此“平均窗长”是个误导性指标，必须按分位数报告——P50 决定稳态吞吐，P95/P99 决定显存峰值与是否触发回退路径。可核查的测量口径是：按窗长分桶（例如按帧数区间分 8～16 桶），每桶记录 (L_a, L_v) 的均值与方差、该桶请求占比、以及该桶下单次前向的激活峰值显存。没有这组直方图，任何关于“动态定标是否稳定”的判断都缺乏依据。</p>\n<p>具体例子：一个 2 秒窗与一个 10 秒窗，若帧率与帧移不变，视觉 token 数近似按 5 倍增长、音频 token 数同样按 5 倍增长，打分矩阵元素数则按 25 倍增长。在 INT8 下打分矩阵若被强制量化，25 倍的规模放大同时放大了量化噪声的累积面；这正是该方案让打分与 softmax 保留高精度累加的负载侧理由，而不只是数值侧理由。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-8\">八 · 并发与批大小：动态定标把批变成数值变量</h3>\n<p>动态 INT8 的缩放因子按 batch 内实际最大绝对值现场计算，s_x = 127 / max|x|。这条规则使批大小从“调度参数”升级为“数值参数”：同一个请求，单独成批与和一条高幅值请求同批，得到的量化步长不同，分类分数因此可能漂移。批越大，max|x| 越容易被长尾样本抬高，缩放因子越小，绝大多数元素的量化分辨率被牺牲。</p>\n<p>可以把单层量化误差的上界写成与批内极值的关系。对均匀量化，步长 Δ = max|x| / 127，元素 x 的误差满足 |e| ≤ Δ/2，于是批内相对误差的量级为：</p>\n<div class=\"formula\">$$\\frac{|e|}{|x|} \\le \\frac{\\max_{b}|x_b|}{254\\,|x|}$$</div>\n<p>该式说明误差上界由批内极值与元素自身幅值之比决定。长尾样本（瞬态强噪声、突发画面变化）会把这个比值推高。工程判断是：动态定标的收益在“批内分布集中”时最大，在“批内分布长尾”时退化。可核查口径为——按批记录 max|x| 的分布、批内幅值的 P99/P50 比值、以及量化前后分类分数的逐样本差值；三者联合才能判断漂移是来自定标还是来自容量。</p>\n<p>代价方面，动态定标本身引入一次额外的归约（求批内最大绝对值）与一次缩放，属于访存受限的小算子；在融合层之前它相对打分矩阵可忽略，但在小批、短窗请求上它会成为固定开销的一部分。因此批大小存在一个由数值稳定性与算子开销共同夹出的可用区间：太小则定标噪声主导、吞吐低；太大则长尾污染定标、且激活峰值显存上升。材料未给出并发数与批大小，故此处只能给出区间存在性的论证与测量口径，不能给出数值。</p>\n<p>具体例子：把一条含突发音频瞬态的请求与九条平稳请求同批，前者的 max|x| 可能比后者高一个量级，于是后九条的量化步长被放大约一个量级，其低幅值特征的有效位数显著减少；若把这些请求拆成两批，平稳批的定标精度恢复，代价是批次数增加、单批利用率下降。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-9\">九 · SLO 由窗长与聚合方式共同定义</h3>\n<p>事件识别的输出按时间窗聚合，SLO 因此不是“单次前向延迟”，而是“窗内事件判定在窗结束后多久给出”。这使 SLO 与窗长耦合：窗越长，可用于计算的时间预算越宽，但单次前向的代价也越高（打分矩阵按平方增长）；窗越短，预算越紧，而短窗恰恰是投影与 FFN 支配、批利用率最难做高的区间。两条曲线交叉处就是该方案最难受的工作点。</p>\n<p>可核查的 SLO 口径必须同时钉住四件事：窗长定义（起止如何对齐两路信号）、帧采样率与帧移、聚合规则（窗内取最大分数还是滑窗投票）、以及计时起点（请求到达 vs 窗结束）。缺任一项，延迟数字不可比。进一步，应报告延迟的分位数而非均值，并按窗长分桶报告，因为长尾窗的延迟由打分矩阵主导，与短窗不在同一代价模型下。</p>\n<p>具体例子：若聚合采用滑窗投票，则同一段输入会被多次前向覆盖，实际计算量是窗数的倍数；此时“每窗延迟”乘以“每请求窗数”才是请求级延迟。忽略这层乘数会系统性低估容量需求。材料未给出窗长、采样率与聚合规则，故本卡只固定口径，不填数值。</p>\n<p>代价侧还要计入量化保护的开销：打分与 softmax 保留高精度累加，意味着这两步不走 INT8 张量核路径，其吞吐低于线性层。在长窗请求中这部分占比上升，SLO 的瓶颈会从“矩阵乘算力”迁移到“高精度累加与 softmax 的访存与指令吞吐”。这是该方案在长窗负载下的结构性代价，也是必须分桶测量延迟的原因。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-10\">十 · 长尾：三类来源与各自的测量口径</h3>\n<p>长尾在本方案里有三个互不相同、不可混用的来源，混淆它们会导致错误的优化方向。</p>\n<ul>\n<li><strong>长度长尾</strong>：窗长分布的尾部，直接放大打分矩阵规模与激活峰值显存。口径：按 (L_a, L_v) 分桶的请求占比与激活峰值。</li>\n<li><strong>幅值长尾</strong>：批内激活分布的尾部，通过 max|x| 拉低动态定标精度。口径：批内 P99/P50 幅值比、量化前后逐样本分数差。</li>\n<li><strong>类别长尾</strong>：事件类别频率不均，稀有类别的分数对量化噪声更敏感（决策边界附近的样本被噪声推过边界）。口径：按类别统计量化前后判定翻转率，而非总体准确率。</li>\n</ul>\n<p>三者对方案的约束方向不同：长度长尾要求分桶调度或对超长窗做降采样/分段；幅值长尾要求限制批内幅值离散度（例如按幅值分桶成批）；类别长尾要求校准样本覆盖稀有类，否则动态定标的统计基础偏向头部类别。材料未给出校准样本数量与分布，因此“校准是否覆盖长尾”在材料层面不可验证，只能作为部署前的必查项列出。</p>\n<p>具体例子：若校准集只含平稳场景，则稀有类别的激活幅值范围未被采样，部署时这些样本的 max|x| 可能超出校准观察到的范围，缩放因子被现场重算而偏离校准时的统计，形成“校准与运行时定标不一致”的隐性漂移。测量口径是把运行时 max|x| 的分布与校准期分布做对比，报告越界比例。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-11\">十一 · 负载塑造方案，方案反过来限制负载</h3>\n<p>负载与方案是双向约束。正向：窗长分布决定打分矩阵是否成为瓶颈，从而决定“打分与 softmax 保留高精度”这一保护是否值得——在短窗主导的负载里，保护的开销占比小、收益明确；在长窗主导的负载里，保护直接压低吞吐上限。批内幅值分布决定动态定标是否稳定，从而决定批大小上限。类别分布决定校准集设计。</p>\n<p>反向：方案一旦固定，就反过来筛掉一部分负载形态。动态 INT8 的批内定标特性使“任意混批”不可行，调度器被迫引入幅值感知的分批约束，这降低了批利用率、抬高了排队延迟；跨注意力保留高精度的选择使长窗请求的单位算力成本高于全 INT8 路径，若 SLO 按短窗标定，长窗请求会被迫走降级路径（降采样或分段融合）。蒸馏后的学生容量则设定了精度天花板，量化噪声只能在剩余裕度内消化，因此负载中高难度样本的比例反过来限制了可用的压缩强度。</p>\n<p>可核查的容量规划口径应把上述双向关系写成可测的量：以“每桶窗长的单请求算力成本 × 该桶请求占比”求期望成本，再除以 SLO 允许的并发上限，得到单位时间可服务请求数；同时以激活峰值显存的分桶 P99 作为显存约束。两个约束取紧者即为容量上限。材料未给硬件档位与实测延迟，故此处只给口径不给数。</p>\n<p>具体例子：若负载中 5% 的请求窗长是 P50 的若干倍，其算力成本按平方增长，则这 5% 可能吃掉与其余 95% 相当的计算预算；此时提高整体吞吐的最有效手段不是换量化方案，而是对长窗做分段融合并把跨段聚合放到高精度路径之外。这属于负载侧改造，而非数值侧改造——正是“方案反过来限制负载”的具体体现。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-12\">十二 · 窗口形态如何反过来定义量化边界</h3>\n<p>该方案的负载单元不是单帧而是同一时间窗内的音视频 token 对：视觉 token 作 query、音频 token 作 key/value，两路长度随窗口长度与帧采样率同步伸缩。这意味着批内序列长度天然不齐，而动态 INT8 的缩放因子 <span class=\"formula\">$$s_x=\\frac{127}{\\max|x|}$$</span> 取自批内实际最大绝对值——一个超长窗或高能量音频片段就能把 <span>max|x|</span> 抬高，使同批其余样本的有效位宽被压缩。于是负载形态直接决定了数值精度：批越大、长度方差越大，定标越偏向长尾极值，短窗样本的分类分数漂移风险越高。可核查的口径是逐层记录批内 <span>max|x|</span> 的分位数分布与量化前后跨注意力打分矩阵的相对误差，而不是只看整批平均激活。</p>\n<p>方案反过来也限制负载：跨注意力打分与 softmax 保留高精度累加，这部分不进 INT8 通道，因此融合层的显存与带宽开销不随量化线性下降；权重离线量化只压缩了线性层与投影，激活仍需现场定标，前向路径上多出一次归约与一次量化转换。工程判断上，应把批大小上限绑定到窗口长度上界而非平均长度，并对超长窗单独成批或退化为静态定标，避免一条长尾请求污染整批缩放因子。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>对方案的作用</th><th>可测口径</th></tr></thead><tbody><tr><td>窗口长度</td><td>决定两路 token 长度与打分矩阵规模</td><td>按窗长分桶的批占比</td></tr><tr><td>批内长度方差</td><td>决定动态定标被极值拉偏的程度</td><td>逐层 max|x| 的 P50/P99 比</td></tr><tr><td>并发与 SLO</td><td>限制批大小上限，进而限制定标样本量</td><td>端到端时延分位与超时率</td></tr></tbody></table>\n<p>材料未给出 token 长度分布、并发数与延迟数字，因此无法核算激活显存的绝对值，也无法判断该方案在 B200 或 GB200 NVL72 上的吞吐收益。可确认的失效条件是：把动态 INT8 当作全链路量化会高估压缩收益；长尾样本下缩放因子偏小导致分数漂移；缺少与静态 INT8、FP8、NVFP4 的对比使方案选择依据不完整。测量上应固定窗长分桶与批构成后再比较量化前后输出，否则负载变化与量化误差无法解耦。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-13\">十三 · 跨注意力融合的算子拆解与量化落点</h3>\n<p>该网络的推理路径可以拆成四类算子：两路编码器前端的逐帧特征提取（卷积或线性投影）、跨注意力融合层的三个投影与打分、融合后的前馈层、以及分类头。量化方案并非均匀铺满全链路，而是按算子对模态对齐误差的敏感度分层处理。线性层与跨注意力投影的权重离线转 INT8 存储，前向时激活按当前 batch 现场定标；而打分矩阵 <span>QK<sup>T</sup></span> 与 softmax 保留较高精度累加。这一分层是整篇论文数值设计的骨架：投影矩阵乘的误差只影响表示的子空间方向，打分矩阵的误差则直接改变音频 token 与视觉 token 的匹配权重，后者会被 softmax 的指数放大后传导到分类输出。</p>\n<p>从 kernel 视角看，量化后的线性层在 Blackwell 上走的是 INT8 矩阵乘指令，累加在 INT32 域完成，再经缩放因子反量化回高精度参与后续非线性。跨注意力打分则不同：Q 与 K 的反量化结果进入高精度乘加，softmax 在 FP32 域做行最大值减法与指数归一化。这意味着同一层内存在两种精度域的交界，交界处的反量化开销与寄存器压力是融合 kernel 设计的实际约束。工程上常见的做法是把投影与打分拆成两个 kernel，或在融合 kernel 内用 warp 级同步分隔两个精度段，代价是额外的中间张量落盘或片上搬运。</p>\n<div class=\"formula\">$$\\hat{y}=\\mathrm{softmax}\\left(\\frac{(Q_v W_q)\\,(K_a W_k)^{\\top}}{\\sqrt{d}}\\right)V_a W_v,\\quad W_q,W_k,W_v\\in\\mathrm{INT8},\\ s_x=\\frac{127}{\\max|x|}$$</div>\n<p>逐项解释：<span>Q_v W_q</span> 是视觉 token 经量化投影得到的 query，<span>K_a W_k</span> 是音频 token 的 key，两者内积构成跨模态对齐打分；分母 <span>√d</span> 是缩放，防止维度增大后点积方差膨胀导致 softmax 饱和；softmax 沿音频 token 维度归一化，得到每个视觉 token 对音频序列的注意力分布；再与 <span>V_a W_v</span> 加权求和，输出融合表示。<span>W_q、W_k、W_v</span> 为 INT8 权重，<span>s_x</span> 是激活的动态缩放因子，按 batch 内最大绝对值现场计算——127 是 INT8 对称量化的正向量化上限，<span>max|x|</span> 是该张量在本 batch 的实际峰值。缩放因子随 batch 变化，因此同一模型在不同请求组合下的数值路径并不完全一致，这是动态量化区别于静态量化的本质特征。</p>\n<p>代价侧要分清两笔账。显存账：权重从高精度降到 INT8，线性层与投影的常驻显存按位宽比例下降，但激活的峰值显存并未同比例下降——动态定标需要先算出 <span>max|x|</span>，这一步要求激活以高精度存在一遍，等于在量化前多一次读带宽。延迟账：INT8 矩阵乘的吞吐高于高精度路径，但每个 batch 的定标归约（求最大绝对值）是一次额外的全张量扫描，batch 越小、张量越碎，这次扫描的相对开销越高。对音频视觉这种 token 长度随窗口变化的负载，定标开销会随时序窗口拉长而线性增长。</p>\n<p>具体例子：设某层激活张量形状为 [B, T, C]，B 为 batch、T 为时间窗内 token 数、C 为通道。动态定标要在 B×T×C 个元素上求最大值，再逐元素乘 <span>127/max|x|</span> 并取整。若 T 随窗口从短窗到长窗翻倍，定标扫描的字节数与量化写回的字节数同步翻倍，而权重读取量不变——于是该层的算术强度被定标环节稀释，roofline 上的工作点向带宽侧偏移。这就是为什么动态量化在长 token 序列上的收益不如在固定短序列上稳定。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-14\">十四 · 数据类型谱系：从 FP16/BF16 到 FP8 与 NVFP4</h3>\n<p>把该论文的 INT8 方案放进 Blackwell 的数据类型谱系里看，才能判断它的位置与替代空间。FP16 有 10 位尾数、5 位指数，动态范围窄但尾数精度高；BF16 用 8 位指数换 7 位尾数，动态范围与 FP32 同阶，适合激活分布跨度大的场景，代价是尾数粗糙。跨注意力打分若用 BF16 累加，点积的舍入误差会随 d 增大而累积；用 FP16 则要防溢出，尤其 softmax 前的指数项。论文选择让打分与 softmax 留在较高精度，本质上是在尾数精度与动态范围之间取保守侧。</p>\n<p>FP8 在 Blackwell 上有两种解释：E4M3 尾数多、范围窄，适合权重与前向激活；E5M2 范围宽、尾数少，适合梯度类张量。推理侧常用 E4M3 配 per-tensor 或 per-block 缩放。相比 INT8 的对称定点，FP8 的浮点表示对长尾分布更友好——同样 8 位，FP8 在接近零的区域有更细的相对分辨率，而 INT8 的绝对步长在全域恒定，长尾样本会把 <span>max|x|</span> 拉大、把小值压成零。这正是该论文动态定标风险点的数值根源：INT8 的定标是全局单尺度，一个离群激活就能牺牲整批的小值分辨率。</p>\n<p>NVFP4 把位宽压到 4 位，配块级缩放（微块共享指数），在 Blackwell 第五代 Tensor Core 上有原生乘加路径。它的显存收益最激进，但尾数只有两位量级，对跨模态对齐这种需要细粒度匹配的打分极不友好。论文未与 FP8、NVFP4 对比，材料中量化方案的选择依据不完整；从机制上判断，融合层的投影可以尝试 FP8 以换取比 INT8 更好的长尾行为，而打分与 softmax 仍应留在 BF16/FP16 域。这是一个可推断的消融维度，但材料未给出实验支撑。</p>\n<table class=\"mini\"><thead><tr><th>数据类型</th><th>位宽</th><th>数值特征</th><th>在该网络中的适配位置</th></tr></thead><tbody><tr><td>FP16</td><td>16</td><td>尾数细、范围窄</td><td>打分与 softmax 的高精度备选</td></tr><tr><td>BF16</td><td>16</td><td>范围同 FP32、尾数粗</td><td>融合表示与前馈层激活</td></tr><tr><td>FP8 E4M3</td><td>8</td><td>块缩放、长尾相对分辨率好</td><td>投影权重的潜在替代</td></tr><tr><td>INT8</td><td>8</td><td>对称定点、全局单尺度</td><td>论文采用的权重与激活格式</td></tr><tr><td>NVFP4</td><td>4</td><td>微块缩放、尾数极短</td><td>不适合打分，仅编码器深层可试</td></tr></tbody></table>\n<p>代价对比要落到具体维度：位宽减半，权重显存与权重读取带宽同步减半，矩阵乘的理论吞吐翻倍；但反量化指令、缩放因子寄存与精度域切换会吃掉一部分收益。对跨注意力层，打分矩阵的尺寸是 <span>B×T_v×T_a</span>，两个模态的 token 长度都可能随窗口变化，这个中间张量的显存峰值往往比权重更早成为瓶颈——把打分留在高精度意味着这部分中间量不享受位宽红利，这是该方案显存收益的上限所在。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-15\">十五 · 累加精度与误差传导路径</h3>\n<p>量化误差的传导不是均匀的，它沿计算图有明确的放大节点。第一段是投影：INT8 权重与 INT8 激活相乘，乘积在 INT32 域累加，反量化时引入一次舍入；这段误差表现为 query 与 key 的方向偏移，量级受缩放因子精度控制。第二段是打分内积：两个带误差的向量做点积，误差随维度 d 部分抵消也部分累积，结果进入 softmax 前被 <span>√d</span> 缩放。第三段是 softmax：指数函数把打分的小误差转成注意力权重的相对误差，若打分误差为 ε，权重误差近似按 <span>ε</span> 的指数敏感度放大——这是论文坚持打分高精度的直接理由。第四段是加权求和与分类头，误差被 attention 权重加权平均后进入 logits。</p>\n<div class=\"formula\">$$\\Delta y \\approx \\sum_i \\frac{\\partial y}{\\partial a_i}\\,\\Delta a_i,\\quad \\Delta a_i \\sim \\frac{\\partial\\,\\mathrm{softmax}}{\\partial s_i}\\,\\Delta s_i,\\quad \\Delta s_i \\sim \\varepsilon_{q}+\\varepsilon_{k}$$</div>\n<p>逐项看：<span>Δa<sub>i</sub></span> 是第 i 个音频 token 注意力权重的扰动，它由打分扰动 <span>Δs<sub>i</sub></span> 经 softmax 雅可比放大；<span>Δs<sub>i</sub></span> 又由 query 与 key 的量化误差 <span>ε<sub>q</sub>、ε<sub>k</sub></span> 在内积中叠加。这个链条说明：投影层的量化误差不会等比例传到输出，而是在 softmax 处被条件数放大。softmax 饱和时（某几个 token 打分远高于其余），雅可比变小、误差被抑制；softmax 平坦时（打分接近），雅可比大、误差被放大。音频视觉事件识别里，声音与画面在同一时间窗内往往只有少数事件显著，打分分布偏饱和，这在一定程度上缓解了误差传导——但长尾样本、弱事件、模态错位窗口会让分布变平坦，此时量化噪声的传导最明显。</p>\n<p>累加精度的工程选择：INT8 矩阵乘的累加器是 INT32，位宽足够容纳 d 次乘加的累积而不溢出，这一点在硬件上由指令保证；真正的风险在反量化后的高精度域——若反量化结果直接截断到 FP16 再做 softmax，尾数损失会叠加到打分上。论文的“较高精度累加”应理解为反量化与打分在 FP32 或至少 BF16 域完成，softmax 的行最大值与指数也在同域。代价是这部分算子的吞吐低于 INT8 路径，融合层的实际加速比因此低于纯线性层的加速比，整网收益被打分环节稀释。</p>\n<p>具体例子：一个 batch 内若混入一个长窗样本，其激活峰值远高于其余短窗样本，动态定标按 batch 内全局最大值取 <span>s_x</span>，短窗样本的激活被压到很低的量化格点，等效位数下降；这些样本的 query/key 误差 <span>ε<sub>q</sub>、ε<sub>k</sub></span> 变大，经打分与 softmax 放大后表现为分类分数漂移。这是动态定标对 batch 组成敏感的直接机制，也是该方案在变长窗口负载下的主要数值风险。缓解手段是按样本或按 token 分块定标，代价是缩放因子数量增加、反量化开销上升。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-16\">十六 · Blackwell 第五代 Tensor Core 与 tcgen05 的落点</h3>\n<p>Blackwell 的第五代 Tensor Core 引入了 tcgen05 指令族，把矩阵乘的累加器从寄存器文件搬到 Tensor Memory（TMEM）——一块与 Tensor Core 紧邻的专用片上存储。对量化推理的意义在于：累加器不再占用寄存器堆，寄存器压力释放给激活搬运与缩放因子计算；同时 TMEM 的带宽与容量支持更大的 tile，单条指令能覆盖更宽的 K 维，减少指令发射与同步开销。INT8 矩阵乘在 tcgen05 上以更大的 MMA 形状执行，累加结果留在 TMEM，反量化时再读出到寄存器或共享内存做缩放。</p>\n<p>2-SM MMA 是另一项结构性变化：一条 MMA 指令可以跨两个 SM 协作执行，共享同一份操作数分块，等效于把 tile 尺寸翻倍而不增加单 SM 的寄存器与 TMEM 压力。对跨注意力打分这种 <span>T_v×T_a</span> 尺寸随窗口变化的算子，2-SM 协作让大 tile 在高利用率下完成，减少因 tile 过小导致的流水线气泡。代价是跨 SM 的同步与数据分发开销，在 token 长度短、tile 填不满时反而成为负担——这解释了为什么小 batch、短窗口的音频视觉请求未必能从 2-SM MMA 拿到线性收益。</p>\n<p>把论文的 INT8 方案映射到这套硬件：权重与激活的 INT8 矩阵乘走 tcgen05 的 INT8 路径，累加在 TMEM 内以 INT32 完成；投影结果读出后做反量化，进入高精度的打分与 softmax。这里有一个精度域切换的落点：TMEM 读出到寄存器的反量化是逐元素的，缩放因子 <span>s_x</span> 需要在片上广播；若打分 kernel 与投影 kernel 分离，中间张量要经共享内存或全局显存传递，带宽开销与延迟都不可忽略。融合设计能把反量化与打分放在同一 kernel 内，用 TMEM 到寄存器的短路径完成切换，但要求 tile 划分与两个精度段的需求匹配。</p>\n<p>代价判断：tcgen05 与 2-SM MMA 提升的是矩阵乘的算术吞吐与 tile 效率，而该网络的融合层里打分与 softmax 留在高精度，这部分不走 INT8 快路径，于是整层的加速比由“投影快路径 + 打分慢路径”的加权决定。若打分占比高（长窗口、大 token 数），硬件红利被慢路径吸收；若投影占比高（通道宽、层数多），红利释放充分。材料未给出硬件档位与实测延迟，无法判断该方案在 B200 或 GB200 NVL72 上的实际收益，这一判断只能停留在机制层面。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-17\">十七 · 精度保护与 kernel 融合的工程取舍</h3>\n<p>该方案最值得借鉴的工程判断是“按算子敏感度分配精度”，而不是把量化当成全链路开关。跨注意力打分与 softmax 的高精度保留，等价于在融合层内划出一条精度边界：边界一侧追求位宽红利，边界另一侧追求对齐保真。这条边界的代价是 kernel 不再单一精度，融合难度上升，反量化与精度切换的指令开销落在关键路径上。工程上要在“融合省带宽”与“分离省复杂度”之间选，前者适合 token 长度稳定、tile 可预划的负载，后者适合窗口变化剧烈、需要动态调度的服务。</p>\n<p>动态定标的实现细节也影响 kernel 形态：<span>max|x|</span> 的归约若在量化 kernel 内做，需要先读一遍激活再写一遍量化结果，读写比接近 2:1；若把归约融进上游算子的 epilogue，激活在写出前就完成峰值统计，可省一次全张量读。这要求上游 kernel 与量化 kernel 共享 tile 划分，是融合设计的又一个落点。对跨注意力层，上游是投影矩阵乘，epilogue 在 TMEM 读出后做反量化与峰值归约，再写入量化激活——这条链路把定标开销摊进矩阵乘的尾部，是 Blackwell 上较自然的实现路径。</p>\n<p>数值监控的工程抓手：量化后要盯两个分布，一是分类分数相对高精度基线的漂移，二是跨注意力对齐分数（softmax 前的打分矩阵）的分布变化。后者更敏感，因为它是误差放大的入口。若对齐分数分布的尾部被压缩、峰值被削平，说明量化噪声已经改变了模态匹配的相对次序，此时应回退打分精度或改用分块定标。材料未给出具体阈值，这一监控只能定性描述。</p>\n<p>具体例子：设融合层通道 C 较宽、窗口 T 较短，投影矩阵乘的 tile 能被 2-SM MMA 填满，INT8 快路径利用率高；打分矩阵 <span>T_v×T_a</span> 较小，softmax 的行归约短，高精度路径的相对开销低——这是该方案收益最好的负载形态。反之，长窗口、窄通道时投影 tile 填不满、打分矩阵膨胀，两头都不占优，动态定标的扫描开销还被放大。这一判断不依赖实测数字，只由算子形状与精度分层推出，可作为部署前容量规划的定性依据。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-18\">十八 · 显存账本的四个户头：权重、激活、KV、工作区</h3>\n<p>把这篇论文的混合跨注意力网络搬到一个具体设备上，第一件事不是看 FLOPs，而是把显存拆成互不挪用的四本账。第一本是权重：视觉编码器、音频编码器、跨注意力融合层的 W_q/W_k/W_v 与投影、前馈层、分类头。第二本是激活：每个 batch 前向时逐层产生的中间张量，其中跨注意力打分矩阵是平方级的，随 token 长度增长最快。第三本是 KV：跨注意力里音频 token 作为 key/value，视觉 token 作为 query，因此缓存的是音频侧的 K 与 V；自注意力若存在则另有自己的 KV。第四本是工作区：INT8 矩阵乘的累加缓冲、softmax 的临时张量、以及动态定标时求 max|x| 的归约缓冲。四本账相加才是真实占用，任何只报权重大小的“模型体积”说法都会低估部署门槛。</p>\n<p>论文的材料没有给出 token 长度分布与批大小，所以绝对数字无法核算；但账本结构可以写成可复算的形式。设视觉 token 数 N_v、音频 token 数 N_a、隐藏维 d、层数 L、批大小 B，则单层跨注意力的打分矩阵元素数为 B·N_v·N_a，若以较高精度（FP16/BF16）保留则占 2·B·N_v·N_a 字节；音频侧 KV 为 2·B·N_a·d·2 字节（K 与 V 各一份）。权重侧若线性层全部 INT8，则字节数约为参数量本身，跨注意力打分与 softmax 保留高精度意味着这部分不享受 INT8 的 4 倍压缩。这就是该方案显存收益的天花板所在：压缩只作用于权重与线性层激活，融合算子的高精度保护区按原精度计账。</p>\n<div class=\"formula\">$$M_{\\text{total}} = \\underbrace{P_{\\text{int8}}}_{\\text{权重}} + \\underbrace{B\\cdot\\sum_l (a_l^{\\text{int8}} + a_l^{\\text{fp}})}_{\\text{激活}} + \\underbrace{2B N_a d\\cdot 2}_{\\text{音频 KV}} + \\underbrace{M_{\\text{ws}}}_{\\text{工作区}}$$</div>\n<p>工程含义很直接：当 N_a 与 N_v 随窗口长度增长时，打分矩阵项按乘积增长，KV 项按 N_a 线性增长，而权重项是常数。短窗口下权重占主导，长窗口下激活与 KV 反超。判断该网络在边缘档位是否可行，取决于窗口长度落在哪一侧——这正是材料未给出、部署前必须自己测的第一个量。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-19\">十九 · 分页与复用：把 KV 从连续大块改成可回收的页</h3>\n<p>音频 KV 的生命周期与请求绑定：一个时间窗的识别请求结束后，这段音频 token 的 K/V 不再有用。若按请求预分配最大窗口长度的连续缓冲，显存利用率会被最长窗口拉低。分页式管理把 KV 切成固定大小的页（例如按 token 数对齐到 16 或 32），按需分配、请求结束即归还页池；页表记录逻辑 token 到物理页的映射，跨注意力读取时按页表拼地址。对本文这类单窗或小批请求，分页的收益不在并发数（材料未给并发），而在碎片控制：不同窗口长度的请求交错到达时，页池不会因为长短不一而留下无法复用的大空洞。</p>\n<p>复用则发生在另一层：同一时间窗内音频与视觉两路编码器的中间特征，若分类头之前有多次前向（例如滑窗重叠），相邻窗口共享的帧特征可以按帧索引缓存，避免重复编码。跨注意力层的 K/V 在同一音频窗口被多个视觉 query 复用时天然共享，不需要重复计算。代价是页表查询与缓存命中判断带来的额外访存与控制开销，在极小 batch 下这部分开销占比会上升，属于典型的“省显存换延迟”的取舍点。</p>\n<p>压缩维度上，KV 本身可以按 INT8 存储再在读取时反量化，但本文明确把跨注意力打分与 softmax 留在高精度，意味着 K/V 若被量化，误差会直接进入对齐分数。稳妥做法是 KV 保持高精度、只压缩权重与线性层激活；若一定要压 KV，应把量化误差限制在 value 侧而非 key 侧，因为 key 参与打分、对噪声更敏感。这一判断来自论文对融合算子的精度保护选择，而非实测。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-20\">二十 · 带宽瓶颈的位置：INT8 省的是字节，不是访存次数</h3>\n<p>动态 INT8 把线性层权重从 2 字节压到 1 字节，矩阵乘的读带宽需求随之减半，这是它最确定的收益。但瓶颈未必在权重读取上。跨注意力打分矩阵的生成需要把 Q 与 K 都读进来做外积，其访存量为 O(N_v·d + N_a·d) 而计算量为 O(N_v·N_a·d)；当 N_v 与 N_a 都较大时该算子偏计算密集，带宽不是瓶颈；当窗口短、N 小、batch 也小时，算子退化为访存主导，此时 INT8 的字节收益才真正兑现。softmax 是纯访存算子，读写整个打分矩阵，保留高精度意味着它按 2 字节/token 对流动，是长窗口下的带宽热点。</p>\n<p>HBM3e 容量与带宽的估算方式：单堆栈容量与堆栈数决定总容量，单堆栈带宽乘以堆栈数得到理论峰值带宽，再乘以可达效率才是有效带宽。B200 与 GB200 NVL72 的具体堆栈配置属于硬件常识范畴，此处不展开；可复算的部分是需求侧——把上一节的 M_total 除以设备可用显存（扣除框架与通信缓冲后的净值），得到“单卡可容纳的并发窗口数”，再把每 token 的字节流量乘以吞吐目标得到带宽需求，两者相除即为该网络在目标 SLO 下的资源缺口。这个比值不依赖具体硬件数字，换设备只需替换分母。</p>\n<p>具体例子：若某窗口下 N_a=N_v=256、d=512、L=8、B=1，则单层打分矩阵为 256×256 个元素，按高精度计约 128 KB，八层累计约 1 MB 量级；音频 KV 为 2·256·512·2 字节即约 512 KB。两者相加已接近一个小模型权重量的量级，说明在中等窗口下激活与 KV 与权重同量级，不能只盯权重压缩率。数字随 d 与 L 线性放大，读者可用自己的配置代入复算。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-21\">二十一 · 卸载与放置：哪些张量可以离开 HBM</h3>\n<p>卸载的判据是“访问频次 × 单次字节数”与“传输代价”的比值。权重在整次前向中被读一遍（每层一次），若设备有更大的主机内存或 NVLink 连接的邻卡，把冷层权重放在外面、按层预取，可以把 HBM 占用压到只剩当前层与下一层。代价是预取延迟必须被计算掩盖：跨注意力层计算密度高，掩盖窗口相对宽；分类头与前馈层若很窄，预取延迟会暴露。对本文的轻量学生网络，层数已被蒸馏削减，卸载的层数有限，收益不如在大模型上显著，但在显存极紧的边缘档位上仍是可行手段。</p>\n<p>激活的卸载更微妙：动态 INT8 的定标需要看到整个 batch 的 max|x|，这意味着激活在被量化前必须完整存在，无法边算边丢。若把激活分块卸载，定标就退化为分块定标，缩放因子按块计算，数值行为与全局定标不同——这是卸载与动态量化之间的真实冲突，材料未讨论，但工程上必须选一边。KV 的卸载则相对干净：请求结束后页可整体换出，换入时按页表恢复，代价是一次连续传输。</p>\n<p>放置策略还应区分编码器与融合层。编码器层是规则卷积或线性堆叠，访存模式可预测，适合静态放置与预取；融合层的跨注意力有数据依赖的打分矩阵，动态形状使其难以提前规划传输。把融合层钉在 HBM、把编码器冷层外置，是符合该网络结构的一种默认放置。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-22\">二十二 · 可复算的显存预算：一张按配置代入的表</h3>\n<p>下面给出预算模板，所有项都以符号表达，读者代入自己的 N_v、N_a、d、L、B 即可得到字节数。表中“精度”列标明该项是否受 INT8 压缩影响，这是本文方案的关键区分：只有标 INT8 的行享受 4 倍字节缩减，标 FP 的行按原精度计。</p>\n<table class=\"mini\"><thead><tr><th>账目</th><th>表达式</th><th>精度</th><th>随何增长</th></tr></thead><tbody>\n<tr><td>线性层权重</td><td>P（参数量）× 1 字节</td><td>INT8</td><td>常数</td></tr>\n<tr><td>线性层激活</td><td>B·Σ a_l × 1 字节</td><td>INT8</td><td>B、token 数</td></tr>\n<tr><td>跨注意力打分</td><td>2·B·N_v·N_a 字节</td><td>FP</td><td>N_v×N_a 乘积</td></tr>\n<tr><td>softmax 临时量</td><td>2·B·N_v·N_a 字节</td><td>FP</td><td>同上</td></tr>\n<tr><td>音频 KV</td><td>2·B·N_a·d·2 字节</td><td>FP</td><td>N_a、d</td></tr>\n<tr><td>工作区</td><td>矩阵乘累加缓冲，按 tile 计</td><td>FP32/FP16</td><td>tile 尺寸</td></tr>\n</tbody></table>\n<p>代入示例（仅演示算法，非实测）：取 d=512、L=8、N_a=N_v=256、B=1，权重按千万参数级估为 10 MB 量级（INT8），线性层激活按每层 B·N·d 量级累加为几 MB，打分与 softmax 各约 0.13 MB/层累计约 2 MB，音频 KV 约 0.5 MB，工作区按 tile 数百 KB。总量落在十几 MB 量级，说明该轻量网络在单窗推理下显存压力主要来自权重而非激活；一旦 B 或窗口长度上升，激活项按乘积反超，预算的重心就从权重搬到融合算子。这个翻转点就是容量规划要盯的阈值。</p>\n<p>预算表还应加一列“是否可压缩”：打分矩阵与 softmax 在本文方案中被明确保护，不能计入 INT8 收益；若后续改用 FP8 或 NVFP4 处理这两项，必须重新评估对齐分数的噪声容限，因为论文的工程判断正是建立在高精度累加之上。把不可压缩项单独列出，才能避免用“权重压缩率”冒充“端到端显存节省”这一常见误算。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-23\">二十三 · 带宽与容量的联立判断：瓶颈落在哪一侧</h3>\n<p>容量判断回答“装不装得下”，带宽判断回答“跑不跑得快”，两者联立才能定位瓶颈。做法是：先用预算表算出单请求的常驻字节 M_req，用可用显存除以 M_req 得到并发上限 C_mem；再用每 token 的字节流量（权重读取摊到每 token、激活读写、KV 读写、打分矩阵读写）乘以目标 token 速率得到带宽需求 R_bw，用有效带宽除以 R_bw 得到带宽允许的并发上限 C_bw。若 C_mem &lt; C_bw，瓶颈在容量，应优先做权重压缩与 KV 分页；若 C_bw &lt; C_mem，瓶颈在带宽，应优先做算子融合与减少打分矩阵的往返读写，而不是继续压权重。</p>\n<p>对本文网络，短窗口小 batch 时权重读取占带宽主导，INT8 直接减半该项，收益明确；长窗口时打分矩阵与 softmax 的读写占主导，而这两项被高精度保护，INT8 帮不上忙，带宽瓶颈会卡在融合层。这意味着该方案的吞吐收益随窗口长度衰减，部署时应把窗口长度作为一维调参量，而不是固定值。材料未给窗口分布，因此这个衰减曲线的具体形状需实测，但方向由账本结构决定，不依赖实验数字。</p>\n<p>最后落到一个具体机制上：动态定标在每次前向时对 batch 内激活求 max|x|，这个归约本身要读一遍激活，等于在量化前多了一次全量访存。若激活已被分页或分块存放，归约就变成跨页扫描，访存次数上升；若把定标与上一层的输出写回合并（在写激活的同时原子更新 max），可省掉这次额外读。这是把显存管理与量化路径接在一起的具体工程动作，也是该方案在真实部署中最容易被忽略的一处带宽开销。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-24\">二十四 · 从窗口到达模式反推调度粒度</h3>\n<p>音频视觉事件识别的请求不是均匀流：它由时间窗切分产生，窗口长度决定两路 token 长度，帧采样率决定单位时间内的请求密度。调度器面对的第一个约束是<b>窗口对齐</b>——同一请求的音频帧与视频帧必须落在同一时间窗内，跨窗拼接会破坏跨注意力对齐语义。因此批处理的基本单位是“一个完整窗口”，而非任意 token 片段。连续批处理（continuous batching）在此处的价值不是把不同请求的 token 拼成一条长序列，而是让短窗口请求在长窗口请求尚未完成跨注意力融合时插入执行，按 step 粒度回收已完成请求的槽位。</p>\n<p>代价体现在激活显存上。动态 INT8 的激活定标按 batch 内实际最大绝对值计算，缩放因子 <span class=\"formula-inline\">s_x=127/max|x|</span> 是批级标量，意味着批内任一长尾样本的极端激活会拉低整批的有效量化分辨率。批越大，定标越稳但长尾污染概率越高；批越小，定标越贴合单样本分布但矩阵乘的 INT8 利用率下降。这是一个显存—精度—吞吐的三向取舍，而不是单纯的吞吐优化。</p>\n<div class=\"formula\">$$T_{\\text{batch}} = \\max_i \\left( L^{\\text{vis}}_i + L^{\\text{aud}}_i \\right) \\cdot t_{\\text{step}} + \\tau_{\\text{fuse}}$$</div>\n<p>其中 <span class=\"formula-inline\">t_step</span> 是单 step 的融合层耗时，<span class=\"formula-inline\">τ_fuse</span> 是跨注意力打分与 softmax 高精度累加的固定开销。由于打分矩阵保留高精度，<span class=\"formula-inline\">τ_fuse</span> 不随 INT8 压缩而缩小，批内窗口长度方差越大，<span class=\"formula-inline\">max_i</span> 项越主导尾延迟。工程判断是：把窗口长度接近的请求聚成一批，比单纯追求大批量更能压尾延迟。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-25\">二十五 · Chunked prefill 在跨模态融合层的切分点</h3>\n<p>Chunked prefill 的常规做法是把长 prompt 的预填切成若干 chunk 交错执行，以平滑 decode 阶段的抖动。在本网络里，切分点不能随意选：视觉 token 作为 query、音频 token 作为 key/value，跨注意力打分要求两路在同一 chunk 内可见。若把视觉 chunk 与音频 chunk 错位切分，打分矩阵会出现部分 key 缺失，对齐分数不可用。可行的切分策略是<b>按时间窗内的帧块成对切分</b>：每个 chunk 携带等长的视觉帧块与音频帧块，融合层在每个 chunk 内完成局部跨注意力，再在 chunk 边界做一次轻量聚合。</p>\n<p>代价是聚合步骤引入额外的中间激活驻留。局部跨注意力的输出需要暂存到所有 chunk 完成，这段驻留显存与 chunk 数成正比，与单 chunk 的 token 数成反比。chunk 切得越细，decode 抖动越小，但聚合驻留与跨 chunk 通信开销越大。对事件识别这类窗口长度中等、请求密度随帧率波动的负载，chunk 粒度的选择应以“单 chunk 内视觉与音频帧块对齐后仍能填满 INT8 矩阵乘的 tile”为下界，否则量化收益被切分开销吃掉。</p>\n<ul>\n<li>机制：成对切分视觉/音频帧块，chunk 内局部跨注意力，chunk 边界聚合。</li>\n<li>代价：聚合中间激活驻留随 chunk 数线性增长；跨 chunk 同步引入 step 间气泡。</li>\n<li>例子：一个 2 秒窗、30 fps 采样得到 60 帧视觉 token 与等长音频帧，切成 4 个 chunk 时每 chunk 15 帧，聚合驻留为 4 份局部打分输出。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-26\">二十六 · 优先级与抢占：分类分数漂移作为抢占信号</h3>\n<p>事件识别的 SLO 不是单一延迟上限，而是“在窗口聚合截止前给出分数”。这给优先级调度一个天然锚点：窗口截止时间越近的请求优先级越高。抢占（preemption）在此处的特殊之处在于，被抢占请求的中间状态不能简单丢弃——跨注意力打分矩阵保留高精度累加，重算代价高于普通 Transformer 的 KV 重放。可行的做法是<b>以 chunk 为抢占粒度</b>：已完成 chunk 的局部融合结果驻留，未完成 chunk 释放激活槽位，恢复时从 chunk 边界续算，而非从头重放。</p>\n<p>抢占信号还应包含数值健康度。动态 INT8 的批级定标对长尾样本敏感，若某请求的激活最大绝对值显著偏离批内中位数，其量化后分类分数漂移风险上升。调度器可以把“定标因子偏离度”作为降优先级或单独成批的依据：偏离度高的请求单独成小批，用更贴合的缩放因子换取精度，代价是牺牲该批的矩阵乘利用率。这是一个用吞吐换尾延迟与精度稳定性的显式交换，而不是隐式容忍。</p>\n<div class=\"formula\">$$\\text{prio}_i = \\alpha \\cdot \\frac{1}{d_i} + \\beta \\cdot \\frac{|\\log s^{(i)}_x - \\log \\bar{s}_x|}{\\sigma_{\\log s}}$$</div>\n<p>其中 <span class=\"formula-inline\">d_i</span> 是距窗口截止的剩余时间，第二项是定标因子偏离度的标准化值。<span class=\"formula-inline\">α、β</span> 的取值决定调度器偏向时效还是数值稳定，材料未给出该网络的实测标定，工程上应以分类分数漂移的在线监控反馈来调。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-27\">二十七 · 分离式预填/解码与跨注意力高精度段的落位</h3>\n<p>分离式（disaggregated）预填/解码把预填与解码放到不同资源池，以减少相互干扰。对本网络，分离的边界应落在<b>跨注意力融合层之前</b>：音频与视觉编码器各自是纯模态内的前向，适合放在预填池批量执行；融合层与分类头是跨模态耦合段，适合放在解码池按请求粒度执行。这样切分的好处是编码器段的 INT8 矩阵乘可以在大批量下跑满，而融合段的高精度打分与 softmax 不被预填的大批激活定标污染。</p>\n<p>代价是两池之间的中间表示传输。视觉 token 与音频 token 的融合前表示需要跨池搬运，带宽开销与 token 长度成正比。若两池部署在同一 NVLink 域内，传输可被吸收；若跨节点，则需按窗口聚合批量传输以摊薄单次开销。另一个代价是融合段无法享受预填池的大批定标稳定性，需要为融合段单独维护一套激活动态范围统计，这增加了校准与监控的工程面。</p>\n<table class=\"mini\"><thead><tr><th>段落</th><th>放置</th><th>量化策略</th><th>主要代价</th></tr></thead><tbody><tr><td>音频/视觉编码器</td><td>预填池，大批</td><td>权重 INT8，激活批级动态定标</td><td>批内长尾拉低定标分辨率</td></tr><tr><td>跨注意力融合</td><td>解码池，请求粒度</td><td>投影 INT8，打分与 softmax 高精度</td><td>高精度段不随压缩缩小，固定开销占比升</td></tr><tr><td>分类头与窗聚合</td><td>解码池</td><td>INT8 线性层</td><td>聚合等待引入尾延迟</td></tr></tbody></table>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-28\">二十八 · 尾延迟的三个来源与压制顺序</h3>\n<p>尾延迟在本负载下有三个可辨识来源，压制顺序应按其对 P99 的贡献排序。第一是<b>窗口长度方差</b>：批内最长窗口决定 step 数，短窗口请求被拖到尾。压制手段是按窗口长度分桶成批，牺牲部分批填充率换方差收敛。第二是<b>融合段固定开销</b>：跨注意力打分与 softmax 保留高精度，其耗时与批大小弱相关，在小批下占比突出。压制手段是把融合段与编码器段分离，让融合段独占资源、避免与预填争抢。第三是<b>动态定标抖动</b>：批级缩放因子随批组成变化，导致同一请求在不同批中量化误差不同，表现为分类分数的小幅漂移，在窗聚合时放大为边界样本的判定翻转。</p>\n<p>压制顺序应是：先分桶降方差，再分离融合段，最后才考虑定标策略。反过来先调定标会掩盖方差问题，因为定标抖动在统计上被大方差淹没，难以定位。工程上可用的判据是：若 P50 与 P99 的比值在分桶后显著收敛，则方差是主因；若收敛有限而融合段耗时占比高，则固定开销是主因。材料未给出该网络的实测延迟分解，这一判据需在部署侧自建埋点。</p>\n<ul>\n<li>机制：窗口长度分桶 + 融合段资源隔离 + 定标偏离度监控。</li>\n<li>公式思路：P99 延迟 ≈ 分桶后方差项 + 融合固定项 + 定标抖动项，按项定位。</li>\n<li>代价：分桶降低批填充率，融合段隔离降低整体利用率，两者都以吞吐换尾延迟。</li>\n<li>例子：同一 2 秒窗请求在混合批中与在等长批中执行，前者 step 数由批内最长窗决定，后者由自身窗长决定，尾延迟差异来自这一项。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-29\">二十九 · 批调度与量化保护的耦合判断</h3>\n<p>调度决策不能独立于量化策略做。动态 INT8 的批级定标意味着“批的组成”本身就是数值参数：把长尾样本与典型样本混批，等于用典型样本的精度补贴长尾样本的吞吐。因此调度器需要把定标偏离度作为一等信号，与截止时间一起参与成批决策。这与纯 LLM 推理中“按 token 数分桶”的做法不同——后者不改变数值路径，前者直接改变量化误差分布。</p>\n<p>具体机制是：在成批阶段计算候选批的 <span class=\"formula-inline\">max|x|</span> 预估（可用上一 step 的激活统计外推），若预估定标因子与批内中位数的偏离超过阈值，则拆分该批。拆分后的小批牺牲矩阵乘利用率，但换回定标贴合度。跨注意力打分与 softmax 的高精度累加在这一步不参与权衡——它是硬保护，不随批调度变化，这也是该方案与全 INT8 路径在调度层面最本质的区别：调度器只需保护线性层与投影的定标质量，融合打分的精度由算子本身锁定。</p>\n<p>落在工程判断上：这套网络的调度设计应以“窗口对齐”为不可协商约束，以“定标偏离度”为可调优先级信号，以“融合段高精度固定开销”为尾延迟的兜底项。三者中任一被忽略，压缩收益都会在尾延迟或分类分数漂移上被抵消。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-30\">三十 · 调度边界：动态定标与跨注意力保护如何约束批处理策略</h3>\n<p>该方案的调度约束首先来自动态 INT8 的定标语义：激活缩放因子 <span class=\"formula\">$$s_x=\\frac{127}{\\max|x|}$$</span> 在每个 batch 前向时按实际最大绝对值现场计算，这意味着批内激活分布直接决定量化网格的粗细。连续批处理把不同时间窗、不同 token 长度的请求拼进同一 batch 时，长尾样本的最大绝对值会主导缩放因子，使多数请求的有效量化位宽被压缩——这是与常规 LLM 连续批处理相反的代价方向：后者追求 batch 填充率，前者要求 batch 内动态范围尽量同质。工程上的可行做法是按音频/视觉 token 长度分桶后再做 chunked prefill，把长窗请求与短窗请求分离到不同 micro-batch，牺牲少量填充率换取定标稳定性；代价是调度器需要维护长度直方图并承担桶间负载不均，尾延迟在桶边界处抬升。</p>\n<p>跨注意力打分与 softmax 保留高精度累加，是抢占与分离式预填/解码设计中的硬约束。打分矩阵 <span class=\"formula\">$$(Q_v W_q)(K_a W_k)^{\\top}$$</span> 若被拆到不同执行流或跨设备重算，高精度中间结果需要以 FP16/BF16 驻留，其显存占用与 token 长度呈二次关系，远高于 INT8 权重。因此在分离式预填/解码架构下，跨注意力融合层不适合被切分到 prefill 与 decode 两个资源池：prefill 侧算出的对齐分数若不能低成本传递，decode 侧就得重算，破坏“预填一次、解码多次”的收益前提。该方案更适配单池内连续批处理加 chunked prefill，把融合层作为不可分割的调度单元，代价是 chunk 粒度受融合层显存峰值限制，长窗请求的首 token 时延被拉长。</p>\n<p>优先级与抢占策略必须绕开量化状态的保存成本。动态 INT8 的激活缩放因子是 per-batch 现场计算的瞬态量，抢占时若需保存中间激活以恢复，就得连同缩放因子与高精度打分矩阵一起换出，换出带宽远大于 INT8 激活本身；而重算则需重新走一遍跨注意力，代价是重复的融合层矩阵乘。两者相权，短请求优先、长窗请求排队、抢占只发生在编码器阶段而非融合层之后，是较现实的折中。尾延迟的压缩不来自更细的抢占粒度，而来自把融合层排除在抢占点之外，并用分桶批处理削掉长尾样本对定标的污染——这一判断在材料未给出硬件与延迟数字的前提下，只能定性成立，具体阈值需以原文实验表为准。</p>\n<table class=\"mini\"><thead><tr><th>调度手段</th><th>对本方案的收益</th><th>系统代价</th></tr></thead><tbody><tr><td>按 token 长度分桶批处理</td><td>稳定动态定标，减少长尾污染</td><td>填充率下降，桶间负载不均</td></tr><tr><td>融合层不切分预填/解码</td><td>避免高精度打分矩阵重算</td><td>chunk 粒度受限，首 token 时延上升</td></tr><tr><td>抢占点限定在编码器阶段</td><td>免去量化状态换出</td><td>长窗请求排队，尾延迟抬升</td></tr></tbody></table>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-31\">三十一 · 切分维度：这套融合网络到底该按什么切</h3>\n<p>音频视觉事件识别网络的并行切分不能照搬大语言模型的分法。它的结构是两路独立编码器加一个跨注意力融合层，融合层的计算量远小于主干，但它是唯一同时触碰两路 token 的算子。按张量并行（TP）切，跨注意力里的 <span>W_q</span>、<span>W_k</span>、<span>W_v</span> 三个投影矩阵可以按头维切分，每卡持有部分注意力头，打分矩阵在卡内本地完成，随后对输出做一次 All-Reduce；这条路径通信量正比于隐藏维乘 batch，是融合层最自然的切法。按流水并行（PP）切则要把编码器前端、融合层、前馈与分类头分到不同卡上，代价是每窗请求都要走一遍流水气泡，而事件识别是短序列、小 batch 的形态，气泡占比会很难看。数据并行（DP）在这类模型上最省事：权重全量复制，各卡吃不同时间窗，只在梯度阶段需要通信——推理时 DP 几乎零通信，代价是显存放不下两份权重。专家并行（EP）对稠密跨注意力网络没有落点，除非把前馈层改成 MoE，那属于另一个话题。</p>\n<p>判断依据可以写成一个粗略的通信-计算比。设融合层单卡计算时间为 <span>T_c</span>，一次 All-Reduce 传输量为 <span>B</span> 字节，链路带宽为 <span>W</span>，则通信占比为</p>\n<div class=\"formula\">$$\\rho=\\frac{B/W}{T_c+B/W}$$</div>\n<p>当 <span>\\(\\rho\\)</span> 超过约三成，TP 的收益就被通信吃掉。对本文这种小模型、短 token、动态 INT8 激活的负载，<span>T_c</span> 本身已被量化压得很小，<span>\\(\\rho\\)</span> 反而更容易被推高——量化让计算变快，却让通信占比上升，这是压缩与并行之间真实的张力。</p>\n<ul>\n<li>具体机制：TP 切注意力头维，跨注意力打分本地完成，输出投影后 All-Reduce 一次。</li>\n<li>系统代价：TP 度数为 <span>N</span> 时，每层通信量随 <span>N</span> 增长而计算量按 <span>1/N</span> 下降，小模型上很快进入通信主导区。</li>\n<li>具体例子：单窗两路 token 各数百、隐藏维数百的融合层，在 TP=2 时 All-Reduce 的数据量已接近单卡计算耗时的量级，TP=4 基本不再划算。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内通信的物理底座</h3>\n<p>Blackwell 机柜内的通信层级决定了上面那个 <span>\\(\\rho\\)</span> 能不能压下去。GB200/GB300 NVL72 用 NVLink 5 把 72 个 GPU 连成一个单跳域，NVSwitch 负责任意两卡之间的全互联交换，因此 TP 组内的 All-Reduce 不需要经过任何跨机网络，走的是交换机内的短路路径。这一点对跨注意力融合层尤其关键：它的 All-Reduce 是逐层、小包、高频的，最怕的是多跳与协议栈开销。把 TP 组约束在同一个 NVLink 域内，等于把 <span>W</span> 拉到域内带宽量级，<span>\\(\\rho\\)</span> 才有机会落回可接受区间。</p>\n<p>但 NVLink 域不是免费的午餐。NVL72 的拓扑意味着一个 TP=8 或 TP=16 的组可以完全落在域内，而一旦 TP 度数超过单机柜可容纳的规模，或者要把多个副本拼成一个更大的 EP 组，通信就必须跨域，此时带宽与延迟都会掉一个档。工程判断很直接：跨注意力融合层的并行组应当优先塞进一个 NVLink 域，宁可降低 TP 度数、用 DP 补吞吐，也不要把融合层切开跨域。</p>\n<table class=\"mini\">\n<thead><tr><th>通信路径</th><th>典型用途</th><th>对本负载的适配</th></tr></thead>\n<tbody>\n<tr><td>NVLink 5 + NVSwitch 域内</td><td>TP 组 All-Reduce、EP 组 All-to-All</td><td>融合层首选，逐层小包延迟低</td></tr>\n<tr><td>域间互联</td><td>PP 跨段激活传递、DP 副本聚合</td><td>短序列下气泡与延迟代价高，慎用</td></tr>\n<tr><td>NIXL 传输层</td><td>KV/激活的跨节点搬运、分离式部署</td><td>适合预填与解码分离时的状态转移</td></tr>\n</tbody>\n</table>\n<p>系统代价上，NVLink 域内的功耗与散热是机柜级约束：72 卡的域意味着单机柜功率密度极高，通信打得越满，交换机与链路的功耗占比越高。对边缘档位部署，这个域根本不存在，通信模型要退回到 PCIe 或单卡，此时并行的意义只剩 DP 与小度数 TP。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-33\">三十三 · All-Reduce 与 All-to-All：两种集合通信的代价结构</h3>\n<p>All-Reduce 是 TP 的主通信原语，环形或树形实现的传输量约为 <span>2(N-1)/N</span> 倍的数据量，度数越大越接近两倍数据量。对跨注意力输出投影后的那一次 All-Reduce，数据量是 batch 乘序列长乘隐藏维乘字节数，动态 INT8 下字节数减半，这是量化对通信的隐性红利——激活量化不只省矩阵乘，也直接砍掉一半的集合通信字节。但要注意，跨注意力打分矩阵与 softmax 保留高精度累加，这部分若参与通信则不能按 INT8 计，实际节省要按混合精度折算。</p>\n<p>All-to-All 出现在 EP 场景：token 按路由结果分发到持有对应专家的卡上，算完再收回。它的代价结构与 All-Reduce 不同——传输量正比于被路由 token 数乘隐藏维，且是稀疏、不规则的，容易出现链路利用率不均。对本文的稠密跨注意力网络，All-to-All 不是主路径；但如果把前馈层做成 MoE 以进一步压参数，All-to-All 就会成为新的瓶颈点，且它与动态 INT8 的定标逻辑冲突：路由后的 token 分布随 batch 变化，激活最大绝对值波动更大，缩放因子更不稳。</p>\n<ul>\n<li>具体机制：All-Reduce 用环状分块归约，传输量 <span>\\(2(N-1)/N \\cdot S\\)</span>；All-to-All 按路由表点对点分发。</li>\n<li>公式思路：单次 All-Reduce 耗时近似 <span>\\(\\alpha + \\beta S\\)</span>，<span>\\(\\alpha\\)</span> 为启动延迟、<span>\\(\\beta\\)</span> 为每字节传输时间；小包场景下 <span>\\(\\alpha\\)</span> 主导。</li>\n<li>系统代价：融合层每层一次 All-Reduce，层数乘启动延迟即为固定开销，短序列下这笔开销摊不薄。</li>\n<li>具体例子：把跨注意力输出投影后的 All-Reduce 与下一层前馈的输入量化合并成一个融合通信步骤，可少一次启动延迟；这是框架层做算子融合时的常见抓手。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-34\">三十四 · NIXL 传输：分离式部署下的状态搬运</h3>\n<p>当预填与解码分离部署时，跨注意力融合层产生的中间状态需要在节点间搬运，NIXL 就是干这件事的传输层。它把显存、主机内存、远端存储抽象成统一的可寻址对象，让推理框架以点对点方式拉取 KV 或激活块，而不必走完整的集合通信。对本文的负载，分离式部署的动机不强——事件识别是单窗短序列，预填与解码的计算比例不像长上下文生成那样悬殊；但如果要做多窗流式识别，把融合层的跨窗状态缓存下来复用，NIXL 的点对点搬运就比重新计算便宜。</p>\n<p>代价在于传输与计算的重叠度。NIXL 的搬运是异步的，但跨注意力融合对时序敏感：下一层的打分要等上一层的融合表示到位，重叠窗口有限。工程上要把传输切成细块、与本地量化定标流水起来，否则 NIXL 的低延迟优势会被同步等待抵消。另一个代价是动态 INT8 的定标依赖 batch 内实际最大绝对值，跨节点搬运的激活若已被量化，接收端无法重新定标，只能接受发送端的缩放因子——这要求两端对 batch 组成有一致视图，否则长尾样本的定标误差会跨节点传导。</p>\n<ul>\n<li>具体机制：NIXL 以注册内存块为单位做 RDMA 式点对点传输，绕开集合通信的全局同步。</li>\n<li>系统代价：传输延迟与本地计算的比值决定分离式是否划算；短窗负载下这个比值偏高。</li>\n<li>具体例子：多窗流式识别时，把上一窗的音频 key/value 缓存经 NIXL 搬到当前窗所在节点，省去重编码，但需保证两端量化缩放因子一致。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-35\">三十五 · 通信何时成为瓶颈：三个可判定的信号</h3>\n<p>第一个信号是计算被量化压扁后的占比变化。动态 INT8 把线性层矩阵乘的吞吐抬上去，单卡计算时间 <span>T_c</span> 下降，而 All-Reduce 的字节数只减半、启动延迟不变，于是 <span>\\(\\rho\\)</span> 上升。当 TP 度数大于 2 且序列长度短于数百 token 时，融合层的通信几乎必然主导。第二个信号是 batch 大小：小 batch 下每次 All-Reduce 的数据量小，启动延迟 <span>\\(\\alpha\\)</span> 占比高，通信效率极差；这正是事件识别单窗到达形态的天然弱点。第三个信号是跨注意力打分矩阵的精度保护——保留高精度的那部分若参与通信，字节数按 FP16 或更高计，量化带来的通信红利被部分抵消。</p>\n<div class=\"formula\">$$T_{\\text{layer}}\\approx \\max\\left(T_c,\\ \\alpha+\\beta S\\right)+\\text{sync}$$</div>\n<p>上式说明层耗时由计算与通信的较大者决定，同步项是二者不重叠的惩罚。要压 <span>\\(T_{\\text{layer}}\\)</span>，要么增大 <span>T_c</span>（合并 batch、拉长序列），要么减小 <span>S</span>（降 TP 度数、激活量化），要么让二者重叠（通信与下一层计算流水）。对本文的部署路径，最现实的是降 TP 度数加 DP 补吞吐：融合层单卡跑，编码器前端按 DP 复制，跨注意力不切分，通信归零。</p>\n<ul>\n<li>具体机制：以 <span>\\(\\rho\\)</span> 与 batch 规模两个维度做并行策略查表，小 batch 短序列直接退到 DP。</li>\n<li>系统代价：DP 复制权重占用显存，动态 INT8 下权重已压到四分之一字节量级，复制代价可接受。</li>\n<li>具体例子：单窗请求、TP=1、DP=4 的配置下融合层零集合通信，代价是四份 INT8 权重常驻显存，换来的是无同步等待的稳定延迟。</li>\n</ul>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-36\">三十六 · 与量化策略的耦合：并行选择反过来约束数值方案</h3>\n<p>并行切分不是独立决策，它反过来约束量化方案。TP 切分后每卡只看到部分注意力头，激活的最大绝对值是局部统计量，<span>\\(s_x=127/\\max|x|\\)</span> 的定标基于分片而非全局，缩放因子与单卡跑出来的不一致，跨卡归约时误差会叠加。这意味着 TP 度数越高，动态 INT8 的定标越偏离全局最优，跨注意力对齐分数的漂移风险越大。反过来，DP 下每卡看到完整激活，定标是全局的，数值最稳——这是 DP 在小模型融合层上除了零通信之外的第二个优势。</p>\n<p>工程判断落在具体机制上：把跨注意力打分矩阵与 softmax 的高精度保护与并行策略绑定——若融合层做 TP，则打分矩阵必须在归约前保持高精度、归约后再量化，否则量化噪声在归约中被放大；若融合层做 DP，则打分矩阵本地完成，高精度保护只需在本地生效，实现更简单。校准样本的分布也要与并行拓扑匹配：TP 分片下的校准应覆盖各分片的激活范围，而不是用全局统计量一刀切。最终，这套网络的并行配置应当由“融合层是否切分”这一个问题决定，其余维度（编码器前端、分类头）按 DP 复制即可，通信路径被压到最短，动态 INT8 的定标逻辑也保持在全局一致的状态。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-37\">三十七 · 融合层量化与并行切分的错位：边界、失效条件与系统代价</h3>\n<p>这套蒸馏加动态 INT8 的方案在单卡、小批、单时间窗的部署形态下自洽，但一旦把跨注意力融合层放进 TP/EP/PP/DP 任一切分维度，量化保护与通信开销就会互相挤压。跨注意力打分矩阵与 softmax 保留高精度累加，意味着这部分算子无法与 INT8 线性层共享同一套低精度集合通信：若把融合层按 TP 切分，<span class=\"formula\">$$T_{\\text{step}}\\approx \\max\\left(T_{\\text{INT8-MM}},\\ T_{\\text{FP-MM}}+T_{\\text{AR}}\\right),\\quad T_{\\text{AR}}\\propto \\frac{S}{B_{\\text{NVLink}}}$$</span>其中 S 为每步 All-Reduce 的字节数，B 为链路带宽。高精度打分矩阵一旦跨卡，All-Reduce 的字节数按精度放大，融合层反而成为 TP 组内最慢的一环；在 NVLink 5 与 NVSwitch 全互联域内，这条路径的代价主要落在集合通信的启动与同步上，而非链路带宽本身。若把融合层放在 PP 边界，跨注意力需要视觉 query 与音频 key/value 同时在场，切分点只能落在编码器之后、融合之前，流水气泡随窗口长度波动而放大。</p>\n<p>EP 与 DP 的适用性更窄。跨注意力是稠密对齐算子，没有 MoE 式的稀疏专家路由，EP 切分只会把一对模态 token 拆到不同 rank，迫使每层插入 All-to-All 重排，收益为零而通信翻倍；DP 复制则让每张卡都持有完整学生网络，动态 INT8 的显存节省被副本数抵消。NIXL 这类点对点传输适合在预填与解码分离的部署里搬运 KV 或中间特征，但本方案的激活定标是 batch 内现场完成的，跨节点搬运已定标的 INT8 激活需要同时传缩放因子，否则接收端无法还原动态范围，传输语义比单纯传 FP16 激活更复杂。可用的工程判断是：融合层留在单卡或单 NVLink 域内，只对编码器分支做 TP/DP，把跨注意力当作不可切分的原子单元。</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>对本方案的适用性</th><th>主要代价</th></tr></thead><tbody><tr><td>TP</td><td>仅编码器分支可行</td><td>高精度打分跨卡触发 All-Reduce，融合层成瓶颈</td></tr><tr><td>PP</td><td>切点受限，只能在融合前</td><td>流水气泡随窗口长度波动</td></tr><tr><td>EP</td><td>不适用，无稀疏路由</td><td>All-to-All 重排，收益为零</td></tr><tr><td>DP</td><td>可行但抵消显存收益</td><td>学生网络副本数增加</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是动态定标与批调度的耦合：连续批处理把长短不一的音频视觉窗口拼进同一 batch，长尾样本的最大绝对值会压低缩放因子 <span class=\"formula\">$$s_x=\\frac{127}{\\max|x|}$$</span>使多数正常样本的有效位宽变窄，分类分数漂移在跨卡聚合时被进一步放大；材料未给出 token 长度分布与批大小，因此无法核算这一漂移的绝对幅度，只能定性判断批内分布越 heterogenous、定标越不稳。其二是通信与量化的精度错配：若为降低 All-Reduce 字节数而把跨注意力打分也压到 INT8，模态对齐误差会直接传导到分类输出，这正是原方案刻意保留高精度的原因。在 B200 或 GB200 NVL72 上，材料未给出硬件档位与实测延迟，无法判断 TP 组规模扩大后集合通信是否真的盖过 INT8 矩阵乘的节省；可确认的是，融合层的高精度保护与并行切分天然冲突，切分越细，保护成本越高。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-38\">三十八 · 精度塌陷：从分数漂移到对齐失配的定位链</h3>\n<p>动态 INT8 的精度塌陷很少表现为整体准确率断崖，而是先出现在跨模态对齐环节。该方案的关键工程选择是：线性层权重离线 INT8、激活按 batch 现场定标，但跨注意力打分矩阵与 softmax 保留较高精度累加。一旦有人把这条保护带拆掉、把打分矩阵也压进 INT8，量化噪声会直接淹没对齐分数——视觉 token 与音频 token 的相似度分布本就被 softmax 的指数放大，低精度打分让原本接近的候选对产生排序翻转，错误经由前馈层与分类头传导为事件类别漂移。诊断顺序应当是自底向上：先看每层激活的最大绝对值 max|x| 与缩放因子 s_x=127/max|x| 的分布，若某层 s_x 在相邻 batch 间跳变超过一个量级，说明该层激活动态范围不稳定，定标本身已不可信；再看跨注意力打分矩阵的熵，熵异常升高通常意味着对齐分数被噪声抹平；最后才看分类头的输出分布偏移。监控上，对每个线性层记录 s_x 的分位数与溢出比例（量化后绝对值超过 127 的激活占比），对跨注意力层单独记录打分矩阵的 top-1 与 top-2 差值均值，这个差值就是对齐置信度的代理指标。具体例子：一个时间窗内音频事件起始帧与画面动作帧错位半帧，高精度打分下 top-1 领先明显，INT8 打分下两者差值被压到噪声量级，分类头在两个相近类别间抖动——这类样本在离线评估里往往被平均掉，只有按窗统计分数方差才能暴露。</p>\n<div class=\"formula\">$$s_x=\\frac{127}{\\max|x|},\\quad \\text{overflow}=\\frac{1}{N}\\sum_i \\mathbf{1}\\left(|x_i|&gt;\\frac{127}{s_x}\\right)$$</div>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-39\">三十九 · OOM 与激活峰值：动态定标的显存副作用</h3>\n<p>动态 INT8 的显存账不能只算权重。权重离线量化后体积固定，但激活定标要求在前向时先拿到当前 batch 的实际最大绝对值，这意味着激活在量化前必须以较高精度驻留，量化只是把矩阵乘的输入转成 INT8，并没有消除高精度激活的瞬时峰值。音频与视觉两路 token 长度随窗口变化，跨注意力打分矩阵规模是 |V|×|A|，窗口拉长时这个矩阵按乘积增长，成为激活峰值的主要来源。工程上的代价是：批大小不能按权重显存来推，必须按最坏窗口长度下的打分矩阵峰值加安全余量来定；一旦按平均窗口配批，长窗口请求就会触发 OOM。定位方法是给每个算子打激活峰值标签，把跨注意力打分、softmax、前馈中间层三处的峰值单独记录，找出随窗口长度超线性增长的那一处。缓解手段不是调低精度，而是对打分矩阵做分块计算，把 |V|×|A| 的中间结果切成能装进显存的分片，逐块 softmax 后累加——代价是额外的核启动与部分重算，吞吐下降换显存安全。具体例子：同一批内混入一个长窗口请求，打分矩阵峰值把整批推到 OOM，分块后该请求单独走慢路径，其余请求维持原批，这是批内异构窗口下必须有的隔离策略。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-40\">四十 · 批抖动：动态定标与批组成的耦合</h3>\n<p>动态定标的缩放因子依赖 batch 内最大绝对值，这使量化精度成为批组成的函数：同一个请求，单独跑和混在大批里跑，激活定标点不同，输出可能不同。批抖动由此产生——调度器为了吞吐把长短窗口、不同模态活跃度的请求拼批，长尾样本（例如音频几乎静音、视觉画面剧烈变化的窗口）会把 max|x| 拉高，s_x 被压小，其余正常样本的激活在量化后有效位减少，分类分数整体偏移。这不是随机噪声，而是与批组成确定相关的系统性偏差，表现为同一请求在不同批下分数不一致、尾延迟样本的准确率明显低于均值。监控上要记录每个 batch 的 max|x| 与批内请求的窗口长度分布，把分数偏移与 max|x| 做相关性分析；若相关性显著，说明定标被长尾样本绑架。工程判断是：对动态 INT8 部署，批调度不能只按吞吐最优拼批，需要按激活动态范围做聚类，把量级相近的请求放在一批，或者对长尾样本走单独定标路径。代价是批利用率下降、调度复杂度上升，但换来的是分数可复现。具体例子：把静音窗口与高动态窗口拼批，前者激活被过度压缩，事件分数向背景类偏移，按动态范围分桶后这类偏移消失，代价是平均批大小变小。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-41\">四十一 · 尾延迟：窗口长度与跨注意力复杂度的叠加</h3>\n<p>音频视觉事件识别的 SLO 按时间窗聚合，尾延迟的来源有两层。第一层是窗口长度本身：token 长度随窗口线性增长，跨注意力打分是两路 token 的乘积，计算量随窗口超线性上升，长窗口请求天然落在延迟分布的尾部。第二层是动态定标的前向依赖：激活必须先算出 max|x| 才能量化，这个归约操作在长 token 序列上是串行的，无法与矩阵乘完全重叠，等于给每个线性层加了一次全局同步。两层叠加，尾延迟不是均值的小幅上偏，而是长窗口请求单独形成的一个延迟峰。定位方法是按窗口长度分桶统计 P99，若 P99 集中在最长桶，问题在跨注意力复杂度；若各桶 P99 都偏高且与批大小相关，问题在定标同步。缓解上，长窗口请求应走独立队列并允许分块流水，把定标归约与上一块的矩阵乘重叠；短窗口请求维持大批以摊薄定标开销。具体例子：窗口长度翻倍时打分矩阵规模翻四倍，若调度器仍按同一批大小接纳，尾延迟直接由打分矩阵的显存带宽访问主导，此时降批比降精度更有效。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-42\">四十二 · 静默降级：没有报错的精度损失最危险</h3>\n<p>最危险的失败模式是不报错的降级。动态 INT8 路径上，溢出激活被截断、定标因子偏小、跨注意力打分被噪声抹平，这些都不会触发异常，推理照常返回分数，只是分数错了。静默降级的典型来源有三：校准样本分布与线上请求分布不一致，导致各层动态范围统计失真；蒸馏后的学生网络容量本就在边界，量化误差把它推过决策边界；跨注意力高精度累加被误配置为全 INT8，保护带消失而无告警。监控必须建立在与高精度参考路径的对照上：定期抽样请求同时跑 INT8 与保留高精度的影子路径，比较分类分数与跨注意力 top-1 对齐结果，把差值超过阈值的样本计入漂移计数；对每层记录溢出比例与 s_x 的历史分位数，偏离基线即告警。回滚策略要分层：先回滚跨注意力层的精度配置（恢复高精度打分与 softmax），这是影响对齐最直接的一环；再回滚动态定标为按层固定缩放因子，牺牲部分压缩收益换分数稳定；最后才整体回退到蒸馏后未量化的学生网络。回滚必须能在不改模型文件的前提下通过配置切换完成，否则故障窗口会被重新部署的时间拉长。具体例子：线上流量从短窗口切到长窗口后，校准样本仍来自短窗口分布，长窗口激活溢出比例上升而分类分数只是轻微偏移，没有告警；影子路径对照发现对齐 top-1 差值均值翻倍，触发跨注意力层精度回滚，分数恢复而吞吐只损失该层的矩阵乘收益——这就是把回滚粒度做细的价值。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>定位手段</th><th>回滚粒度</th></tr></thead><tbody><tr><td>精度塌陷</td><td>打分矩阵熵升高、top-1/top-2 差值缩小</td><td>逐层 s_x 分位数与溢出比例</td><td>跨注意力层恢复高精度累加</td></tr><tr><td>OOM</td><td>打分矩阵激活峰值随窗口超线性增长</td><td>按算子打峰值标签、分块计算</td><td>长窗口请求隔离慢路径</td></tr><tr><td>批抖动</td><td>同请求跨批分数不一致</td><td>max|x| 与窗口分布相关性分析</td><td>按动态范围分桶拼批</td></tr><tr><td>尾延迟</td><td>P99 集中在最长窗口桶</td><td>按窗口长度分桶统计</td><td>长窗口独立队列、定标与矩阵乘重叠</td></tr><tr><td>静默降级</td><td>影子路径分数漂移计数上升</td><td>高精度对照抽样</td><td>动态定标回退为固定缩放因子</td></tr></tbody></table>\n<p>这套诊断体系落在一个工程判断上：动态 INT8 的可运维性取决于定标状态是否被当作一等监控对象。把每层的 max|x|、s_x、溢出比例与跨注意力打分置信度做成随请求可追溯的指标，故障定位就从“准确率掉了”变成“哪一层、哪个窗口长度、哪种批组成下定标失准”，回滚也才能停在最小代价的那一层而不是整体回退。对 Blackwell 档位上的部署，这意味着量化配置、调度分桶与影子对照三条链路必须一起设计，任何一条缺失都会让静默降级在无告警状态下累积。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-43\">四十三 · 动态定标的分布陷阱与精度塌陷的可观测信号</h3>\n<p>这套方案最脆弱的环节不在权重侧，而在激活侧：<span class=\"formula\">$$s_x=\\frac{127}{\\max|x|}$$</span> 的分母取自当前 batch 内实际最大绝对值，于是缩放因子本身是随机变量。当一个时间窗内音频分支出现突发瞬态（敲击、爆音）而视觉分支仍处于低动态场景时，两路 token 的激活幅值差被压缩进同一 INT8 网格，小幅值通道的有效位宽被长尾样本吃掉，跨注意力打分虽以较高精度累加，但进入打分前的 Q/K/V 投影已被粗量化，对齐分数分布整体偏移。工程上这表现为分类分数漂移而非报错——即静默降级：top-1 类别不变但置信度整体下移，或相邻时间窗的事件边界抖动。监控应落在跨注意力打分矩阵的熵与分数分布的 KL 散度上，与蒸馏后未量化基线逐窗比对，阈值触发即回退到高精度投影路径，而不是等端到端准确率掉点才发现。</p>\n<p>第二类失败是批抖动与尾延迟。动态定标要求同一 batch 内所有样本共享一次 max 归约，批大小一变，缩放因子与矩阵乘的 tiling 效率同时变化；单窗请求与小批请求混跑时，尾延迟由最长 token 序列决定，而短窗请求被迫等待同一归约。这与连续批处理中 KV 分页的抖动叠加，表现为 P99 抬升而 P50 平稳。定位手段是把每层的 <span class=\"formula\">$$\\max|x|$$</span> 与批内 token 长度分布一并打点，观察尾延迟窗口是否与 max 值尖峰同相位；若是，则改为按样本分组定标或对长尾样本单独走高精度分支。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>机制归因</th><th>处置</th></tr></thead><tbody><tr><td>置信度整体下移、类别不变</td><td>长尾样本压低 s_x，投影粗量化</td><td>打分/softmax 保高精度，回退投影</td></tr><tr><td>P99 抬升、P50 平稳</td><td>批内 max 归约与 token 长度耦合</td><td>分组定标、长短窗分流</td></tr><tr><td>显存突增后 OOM</td><td>误按全 INT8 估算激活，实际打分矩阵仍高精度</td><td>按融合层实际精度重算峰值</td></tr></tbody></table>\n<p>OOM 的根因常是容量规划错位：把动态 INT8 当成全链路量化，按 INT8 激活字节数估算峰值，而跨注意力打分矩阵与 softmax 保留高精度，其显存随 token 长度平方增长，长窗请求下这一项才是峰值主项。回滚策略应分层：权重侧离线 INT8 可保留，激活侧按层开关动态定标，跨注意力投影单独配置精度档；校准样本分布一旦偏离线上窗口分布，先降级融合层精度保护而非整体回退到 FP 模型，以保住大部分吞吐收益。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-44\">四十四 · 基准表的三个空位：模型、硬件、负载</h3>\n<p>读这篇论文的实验表，第一件事不是看准确率涨了多少，而是确认三列是否填满：模型口径、硬件档位、负载形态。材料对这三列都留了空位——未给出数据集规模、未给出硬件档位与延迟指标、未给出批大小与并发数。这意味着任何“蒸馏加动态 INT8 在 Blackwell 上带来 X 倍吞吐”的转述都是编造。可复现的读法是：把论文的实验表当作<strong>相对口径表</strong>而非绝对性能表，只接受同一表内、同一硬件、同一 batch 下的横向比较，跨表数字一律视为不可比。</p>\n<p>具体到模型口径，教师网络与学生网络的通道数、层数、跨注意力头数决定了参数量级，而材料只说明“缩小通道与层数，保留跨注意力结构”。因此基准表里至少要有三行：教师 FP32/FP16 基线、学生蒸馏后高精度基线、学生动态 INT8 部署版。缺少中间那行，就无法把精度损失拆成“蒸馏容量损失”与“量化噪声损失”两部分——这是该论文消融维度里最该有却材料未给出的一项。工程上判断一张表是否可信，看它是否把学生高精度基线单列；只给“教师 vs 量化学生”的对比，等于把两种误差源混在一起。</p>\n<p>硬件档位同理。动态 INT8 的收益来自矩阵乘从 FP16 降到 INT8 的算力倍率与权重带宽减半，而这两项在 SM100 上与在边缘 SoC 上完全不同量级：B200 的 INT8 张量核吞吐与 HBM 带宽决定了算子是否 compute-bound，边缘档位则往往先撞带宽墙。材料未给硬件，因此论文报告的加速比只能理解为“该硬件上、该 batch 下”的局部结论。若要在 GB200 NVL72 上复用这条路径，必须重新测：同一学生网络在 FP16 与 INT8 下的单窗延迟，以及 batch 放大后动态定标是否仍稳定。</p>\n<div class=\"formula\">$$T_{\\text{window}} = T_{\\text{enc}}^{a} + T_{\\text{enc}}^{v} + T_{\\text{xattn}} + T_{\\text{ffn}} + T_{\\text{head}}$$</div>\n<p>这个分解式是读延迟数字的骨架：音频编码、视觉编码、跨注意力、前馈、分类头五段中，只有跨注意力与前馈走 INT8 矩阵乘，两路编码器前端若保持高精度则不受益。于是“端到端加速比”必然小于“融合层加速比”，论文若只报后者，属于口径放大。举例：一个时间窗内视觉 token 数远多于音频 token 数时，视觉编码段占比上升，INT8 只压缩融合段，端到端收益被稀释——这正是材料未给 token 长度分布所掩盖的关键变量。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-45\">四十五 · batch 与并发：动态定标的分母</h3>\n<p>动态 INT8 的核心机制是每个 batch 前向时按实际最大绝对值现场算缩放因子：</p>\n<div class=\"formula\">$$s_x=\\frac{127}{\\max_{i\\in\\text{batch}}|x_i|},\\qquad x_q=\\mathrm{round}(x\\cdot s_x)$$</div>\n<p>注意分母是 batch 内全局最大值。batch 越大，越可能混入一个长尾样本把 max|x| 抬高，导致其余样本的量化步长被压粗、有效位宽下降。这与静态量化按校准集统计的固定缩放因子形成对照：静态量化对分布漂移不敏感但对单批异常值鲁棒，动态量化反之。材料明确指出“动态定标对 batch 内激活分布敏感，长尾样本会拉低缩放因子精度”，这是该方案的主要数值风险点，也是基准表必须标注 batch 大小的原因——脱离 batch 谈 INT8 精度损失没有意义。</p>\n<p>并发维度上，事件识别按时间窗聚合输出，请求以单窗或小批到达。单窗推理时 batch=1，动态定标退化为逐样本定标，数值最精确但矩阵乘的 INT8 利用率最低；连续批处理把多个窗拼批后，INT8 吞吐上升而缩放因子被最坏样本主导。工程判断是：把定标粒度从“整批一个 scale”改为“按 token 组分块定标”能缓解长尾污染，代价是额外的归约开销与 kernel 复杂度。材料未给并发数，因此无法核算在 NVL72 上多副本并行时，单副本 batch 该取多大才能同时满足 SLO 与数值稳定。</p>\n<p>代价侧写：batch 翻倍使激活显存线性上升，而 INT8 只把每元素字节数从 2 降到 1，因此显存节省上限是激活部分的 50%，权重部分同理。若某层激活占该层总占用的大头，INT8 的显存收益接近减半；若权重占大头，则收益取决于权重离线量化的比例。材料未给分层占用，所以“显存降低一半”这类表述只能限定在“被量化的线性层与跨注意力投影”范围内，不能外推到整网。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-46\">四十六 · 指标口径：TTFT、TPOT 与吞吐在事件识别里的变形</h3>\n<p>事件识别不是自回归生成，没有逐 token 解码，因此 TTFT/TPOT 这对 LLM 指标要重新映射。TTFT 对应“一个时间窗从输入到首个事件分数的延迟”，TPOT 没有直接对应物，取而代之的是<strong>窗口吞吐</strong>（每秒处理的时间窗数）与<strong>窗口时延</strong>（单窗端到端时间）。把 LLM 的 TPOT 硬套到分类网络上会得出无意义的“每 token 时间”，因为输出只有一个类别分布。读论文表格时若见到“吞吐提升”字样，必须确认它是 windows/s 还是 samples/s，以及是否含预处理（音频帧提取、视频解码）——材料的数据管线显示两路前端各自编码，预处理往往不在 GPU 计时内，属于常见的口径缺口。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>事件识别中的定义</th><th>受量化影响的部分</th><th>口径陷阱</th></tr></thead><tbody><tr><td>单窗时延</td><td>输入窗到类别分数输出</td><td>仅融合层与前馈的 INT8 矩阵乘</td><td>是否含两路编码器前端</td></tr><tr><td>窗口吞吐</td><td>单位时间完成的窗数</td><td>batch 内 INT8 利用率</td><td>是否含预处理与后聚合</td></tr><tr><td>激活显存峰值</td><td>前向中最大激活占用</td><td>被量化线性层减半</td><td>是否含跨注意力打分矩阵（保留高精度）</td></tr><tr><td>功耗</td><td>单位窗能耗</td><td>INT8 算力密度提升</td><td>是否含空闲功耗</td></tr></tbody></table>\n<p>跨注意力打分矩阵与 softmax 保留较高精度，这一条直接改变显存与延迟口径：打分矩阵是 O(N_v·N_a) 的中间量，若它不量化，则该部分的显存不享受 INT8 减半，且 softmax 的高精度累加引入额外寄存器压力。材料把这一点列为“区别于全 INT8 的关键工程选择”，因此在基准表里，“INT8 覆盖率”应作为独立列出现——只报“权重与激活均 INT8”而不说明打分矩阵例外，会系统性高估压缩收益。举例：视觉 token 与音频 token 各为数百量级时，打分矩阵元素数可达十万量级，若以 FP16 存放，其占用可能超过若干被量化线性层的权重节省，净显存收益因此打折。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-47\">四十七 · 哪些提升不可比：四类跨表陷阱</h3>\n<p>第一类，精度口径不可比。教师软标签蒸馏后的学生网络，其分类分数分布已被教师平滑过，与真实标签训练的基线在置信度校准上不同。若一方报 top-1 准确率、另一方报 mAP 或事件级 F1，数字不可横向比较。材料未给指标定义，读表时应先找“同一指标、同一聚合方式”的脚注。</p>\n<p>第二类，量化范围不可比。全 INT8（含打分矩阵）与“线性层 INT8 + 打分高精度”是两种不同方案，前者压缩收益更大但模态对齐误差可能放大，后者保守。论文未与静态 INT8、FP8 或 NVFP4 对比，材料明说“量化方案的选择依据不完整”。因此在 Blackwell 语境下，不能把该论文的 INT8 收益直接对标 FP8 或 NVFP4 的吞吐——FP8 在 SM100 上有原生张量核路径且动态范围更宽，NVFP4 的块缩放机制与逐 batch 定标是两套不同的数值哲学，三者不可互换引用。</p>\n<p>第三类，蒸馏与量化的收益不可加。学生网络容量缩小带来的精度损失与 INT8 噪声带来的损失不是线性叠加：容量小的网络对量化噪声更敏感，因为冗余参数少、误差无处摊薄。材料未给消融，但从机制上可推断，把“蒸馏带来的模型缩小倍数”与“量化带来的显存减半”相乘得出“总压缩倍数”是错误算法——两者作用于不同维度（参数量 vs 每参数字节），且精度代价耦合。</p>\n<p>第四类，硬件档位不可比。同一 INT8 kernel 在 B200 与边缘档位上的瓶颈不同：前者可能 compute-bound，收益接近算力倍率；后者 memory-bound，收益接近带宽倍率。材料未给硬件，故论文的加速比不能移植到 GB200 NVL72 的容量规划里。工程判断是：在 NVL72 上评估这条路径，先测融合层在 FP16 与 INT8 下的实际耗时占比，若融合层只占端到端 30%，则 INT8 的理论端到端上限就是该段的加速比乘以 0.3，其余段必须另找优化（如编码器前端用 FP8 或 token 压缩）。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-48\">四十八 · 读表顺序：从校准样本到分数漂移</h3>\n<p>推荐的读表顺序不是从准确率开始，而是从校准环节倒推。材料说明量化校准只需少量样本统计各层激活动态范围，权重离线转 INT8，蒸馏后不再重训。于是第一问是：校准样本的分布是否覆盖了推理时的长尾窗？若校准集偏窄，动态定标在真实 batch 上遇到的 max|x| 会超出校准统计，缩放因子失配，分类分数漂移。监控重点在材料里已给出——量化后分类分数漂移与跨注意力对齐分数分布变化——但没有阈值。工程上应把“对齐分数分布的 KL 散度”作为上线前门禁指标，而不是只看准确率均值。</p>\n<p>第二问是跨注意力层的敏感度。材料未给该层对量化的敏感度数据，但机制上可推断：打分矩阵保留高精度正是为了不让量化噪声淹没对齐分数，因此该层的量化误差主要来自 Q/K/V 投影的 INT8 权重与激活。若投影权重离线量化后分布偏移，query 与 key 的点积角度会被扰动，softmax 后的注意力权重随之偏移，误差经 V 投影传导到融合表示。这条链路的代价是分类分数漂移而非延迟——属于精度侧风险，不体现在吞吐表里。</p>\n<p>第三问才是吞吐与显存。此时应确认表中是否区分了“仅权重 INT8”与“权重加激活 INT8”两档：前者只减带宽不减算力，后者才触发 INT8 张量核路径。材料明确方案是权重离线、激活动态，属后者，但打分矩阵例外。若论文只报一档，无法判断收益来自带宽还是算力，也就无法在 Blackwell 上判断是否值得为动态定标付出额外归约开销。</p>\n<p>最后落在工程判断上：这条路径的可部署性取决于三个未在材料中闭合的量——校准样本对长尾窗的覆盖率、batch 内激活分布的离散度、以及融合层在端到端延迟中的占比。三者任一不满足，动态 INT8 的收益就会被分数漂移或 Amdahl 上限吃掉；因此在把该论文写进容量规划前，必须先在目标硬件上用同一学生网络跑一遍 FP16 与 INT8 的对照，把融合层耗时占比与对齐分数漂移同时测出来，而不是引用论文表格里的相对数字。</p>\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-49\">四十九 · 迁移到别的融合结构：先看跨注意力是不是瓶颈</h3>\n<p>这套方案的可迁移性不取决于“蒸馏+动态 INT8”这两个词，而取决于被压缩网络里跨注意力融合层占多少计算与显存。教师网络的结构是两路编码后进入跨注意力融合层，视觉 token 作 query、音频 token 作 key/value；蒸馏时学生缩小通道与层数但保留跨注意力结构。迁移到别的模型时，第一步不是套用蒸馏损失，而是做一次算子级剖面：把融合层的打分矩阵规模、投影层权重占比、前馈层占比分别量出来。若融合层只占端到端 FLOPs 的一小部分（例如编码器前端是重卷积或重 ViT），那么“跨注意力打分保留高精度”这条保护措施带来的收益上限就被压低了——你保护的是一个本来就不大的算子，压缩收益主要来自编码器，而编码器并不在这个方案的量化保护范围内。</p>\n<p>反过来，如果目标模型的融合是早期拼接或简单相加，没有可保护的跨注意力打分矩阵，那么这套方案退化为“蒸馏+动态 INT8 线性层”，此时它的差异化价值消失，应该直接与静态 INT8、FP8 方案比较，而不是沿用本文的高精度累加策略。判断准则可以写成一句话：融合算子是否同时满足“计算占比可观”和“对数值扰动敏感”两个条件。两者都满足才值得照搬；只满足前者，照搬量化保护是浪费；只满足后者，应优先考虑保留融合层高精度而把压缩压力放到别处。</p>\n<p>代价层面要算清楚：动态 INT8 的激活定标是每次前向现场做一次归约求最大绝对值，<span class=\"formula\">$$s_x=\\frac{127}{\\max|x|}$$</span>，这意味着每个被量化的激活张量多一次全局归约与一次逐元素缩放。对跨注意力投影这类中小张量，归约开销可能被矩阵乘掩盖；但对大激活张量，归约本身会成为延迟项，尤其在小 batch、低延迟档位上，归约的固定开销摊不薄。迁移到激活张量更大的模型时，这一点必须先测，不能假设动态定标免费。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-50\">五十 · 蒸馏环节的迁移条件：教师软标签是否携带对齐信息</h3>\n<p>蒸馏损失由三项组成：学生与教师软标签的 KL 散度、学生与真实标签的交叉熵、跨注意力层中间特征的均方误差。第三项是这套方案能在压缩后保住模态对齐的关键——它把教师的跨注意力中间表示作为监督，而不只是输出分布。迁移到别的任务时，这一项是否可用取决于教师中间特征是否可对齐：学生与教师的层数、通道数不同，中间特征 MSE 需要插值或投影对齐，若对齐方式粗糙，这一项会变成噪声监督而不是有效信号。</p>\n<p>更实际的判断是：目标任务是否存在“输出正确但融合错误”的失败模式。音频视觉事件识别里，两路信号在同一时间窗内对齐，融合错误会直接体现为分类错误，所以中间特征监督有明确靶子。迁到输出空间更宽松的任务（例如生成式多模态输出、检索排序），软标签的 KL 项承载的信息量更大，中间特征 MSE 的边际收益下降，此时应把蒸馏预算从特征对齐转向输出分布匹配，并相应放宽融合层的量化保护——因为对齐误差不再直接传导到单一分类分数。</p>\n<p>工程代价上，蒸馏是一次性离线成本，但它决定了量化校准的起点。学生容量越小，量化误差越依赖校准样本分布；材料明确说蒸馏后不再重训，量化误差主要通过学生容量与校准样本分布控制。迁移时若目标模型的学生容量压得更狠，校准样本就必须覆盖长尾输入分布，否则动态定标的 <span class=\"formula\">$$\\max|x|$$</span> 会被正常样本主导，长尾样本量化后漂移。这不是口号，是校准集设计的具体约束：校准样本要按输入窗口长度、信噪比、模态缺失情况分层采样。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-51\">五十一 · 动态 INT8 的适用边界：batch 分布与长尾</h3>\n<p>动态定标的核心风险在材料里已经点明：对 batch 内激活分布敏感，长尾样本会拉低缩放因子精度。机制上，<span class=\"formula\">$$s_x=127/\\max|x|$$</span> 用的是 batch 内最大绝对值，一个极端激活值会把缩放因子压小，使其余正常值的量化台阶变粗，等效于对多数样本降精度。批越大，混入极端值的概率越高；批越小，归约开销摊不薄且定标方差大。这条边界决定了该方案不适合“大 batch 混合长尾流量”的在线服务，除非做逐样本定标或按输入长度分桶。</p>\n<p>迁移到 Blackwell 时还要面对精度格式的选择问题。材料未与静态 INT8、FP8、NVFP4 对比，量化方案的选择依据不完整。工程判断是：动态 INT8 的优势在于无需重训、校准成本低，适合“已有模型、快速上线”的场景；若目标模型允许重训或已有充分校准管线，FP8 在 Blackwell 上的张量核心路径更直接，NVFP4 则在权重侧压缩更激进但激活动态范围更窄、对长尾更敏感。把动态 INT8 迁到 Blackwell 不等于自动获得收益，要先确认框架是否把动态定标融合进 kernel，否则归约与缩放会以额外 kernel 形式出现，吃掉矩阵乘节省的时间。</p>\n<p>具体例子：一个音频视觉事件识别服务，窗口长度随请求变化，音频 token 与视觉 token 长度都浮动。若按固定 batch 聚合不同长度请求，最长窗口的激活会主导 <span class=\"formula\">$$\\max|x|$$</span>，短窗口请求被过度粗糙量化。可行做法是按 token 长度分桶、桶内定标，代价是桶边界带来额外调度复杂度与显存碎片；不做分桶就得接受分类分数在短窗口上的漂移，并在 SLO 上留出精度余量。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-52\">五十二 · 规模上限：这套方案在哪里触顶</h3>\n<p>规模上限来自两个方向。其一是学生容量：蒸馏把教师能力压进更小网络，量化再压一层，两层压缩叠加后，融合层的表示精度由学生容量决定。材料未给量化后精度损失幅度，但机制上可判断：当学生容量接近任务所需下限时，动态 INT8 的量化噪声会直接吃掉蒸馏好不容易保住的对齐能力，此时继续压容量的边际收益为负。其二是激活定标的 batch 依赖性：模型越大、激活张量越多，逐张量归约的固定开销越多，动态定标从“被矩阵乘掩盖”变为“显式延迟项”的临界点越早到来。</p>\n<p>因此这套方案的上限不是“能压多大模型”，而是“在给定延迟预算下，融合层能保留多少精度”。迁到更大模型时，正确做法是把量化保护范围从“跨注意力打分与 softmax”扩展到“所有对最终输出敏感的小算子”，而把动态 INT8 限制在大线性层上；这与本文原方案的保护边界不同，需要重新做敏感度扫描。材料未给跨注意力层对量化的敏感度数据，迁移时必须自己补这一项，否则保护范围是拍脑袋定的。</p>\n<p>显存侧的上限同样要算：动态 INT8 降低权重存储与矩阵乘代价，但激活定标需要保留高精度累加与打分矩阵，这部分显存不随量化缩小。当序列长度或 batch 增大使打分矩阵成为显存主项时，量化带来的显存节省被稀释，此时应转向 KV/激活的分块或重计算，而不是继续加大量化力度。</p>\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-53\">五十三 · 不适用的场景与替代路径</h3>\n<p>明确不适用的情况有三类。第一类是全链路 INT8 诉求：本文方案对跨注意力打分与 softmax 保留高精度，若业务要求端到端全 INT8 以匹配特定硬件路径，这套方案的保护措施反而成为阻碍，应改用对打分矩阵做对数域或分块量化的专门方案。第二类是融合层占比极低的模型，压缩收益主要在编码器，应把蒸馏与量化预算移到编码器侧，融合层维持原精度。第三类是输入分布极长尾且无法分桶的服务，动态定标的 batch 依赖性无法通过工程手段消除，应改用静态校准加逐通道缩放，牺牲一些自适应换稳定性。</p>\n<p>替代路径的取舍可以用一个简单判据：是否需要重训。本文方案的最大工程价值是“不重训即可压缩”，代价是压缩率受学生容量与校准质量限制。若允许重训，量化感知训练能把动态定标的误差纳入优化目标，通常能在同等精度下压得更狠；若不允允许重训但允许换精度格式，FP8 在 Blackwell 上是更省工程的选择，前提是激活动态范围可控。三条路径不是互斥，实际部署常是“蒸馏学生 + FP8 权重 + 动态 INT8 激活”的混合，但混合后保护边界要重新划，不能照搬本文的跨注意力高精度累加设定而不做验证。</p>\n<p>最后落到一个具体机制上：迁移这套方案时，最先要改的不是损失函数，而是量化保护清单。把目标模型的算子按“对输出敏感度 × 计算占比”排序，敏感度高且占比小的算子保留高精度，占比大的线性层走动态 INT8，融合层打分矩阵单独做敏感度测试后再决定是否保护。这个清单决定了压缩收益与精度损失的分配，也决定了这套方案在新模型上是真迁移还是名义迁移。</p>\n\n\n<h3 id=\"paper-efficient-audio-visual-event-recogni-2026-sec-54\">五十四 · 迁移边界：什么能搬、什么必须重算</h3>\n<p>这套“蒸馏缩容 + 动态 INT8”的组合可迁移的部分是流程骨架：教师软标签与中间特征监督、学生保留跨注意力拓扑、权重离线量化、激活按 batch 现场定标、打分矩阵与 softmax 走高精度累加。不可直接搬的是数值契约。跨注意力打分对量化噪声的敏感度与模态间时间对齐精度强相关，音频 token 与视觉 token 长度随窗口变化，意味着 <span class=\"formula\">$$s_x=\\frac{127}{\\max|x|}$$</span> 中的 max|x| 在窗口拉长时被长尾帧主导，缩放因子偏小、有效位宽被压缩，分类分数漂移先于精度指标暴露。迁到新领域时必须重做两件事：重新标定“哪些算子留在高精度”的白名单（打分、softmax、可能的层归一化），以及用目标域窗口长度分布重采校准集，而不是复用源域校准样本。</p>\n<p>失效条件可以列成一张判断表，而不是口号：</p>\n<table class=\"mini\"><thead><tr><th>迁移场景</th><th>判断</th><th>系统代价来源</th></tr></thead><tbody><tr><td>同架构、同窗口长度分布</td><td>可直接复用，仅换校准集</td><td>校准样本采集成本，一次性</td></tr><tr><td>窗口长度方差显著变大</td><td>需改为分桶定标或静态+动态混合</td><td>激活显存与定标开销上升，矩阵乘有效位宽下降</td></tr><tr><td>融合层从跨注意力换成早期拼接</td><td>不适用，精度保护白名单失效</td><td>无对齐算子可保护，量化误差直通分类头</td></tr><tr><td>目标硬件只支持整型通路</td><td>不适用，高精度累加无法保留</td><td>对齐误差放大，需回退到更高位宽</td></tr></tbody></table>\n<p>规模上限不在模型参数量，而在 batch 维度。动态定标的收益随 batch 增大而摊薄单次定标开销，但 batch 内激活分布的离散度同时上升，长尾样本把 max|x| 抬高、其余样本量化步长变粗，等价于用吞吐换数值稳定性。工程判断是：把动态 INT8 用在编码器线性层与跨注意力投影上，把打分与 softmax 固定在高精度，并按窗口长度分桶控制 batch 组成，使同桶内激活动态范围可比。若目标档位是 B200/GB200 NVL72 这类高带宽平台，瓶颈会从矩阵乘转向定标与规约的访存，此时应优先评估 FP8 或 NVFP4 路径而非继续压 INT8 位宽——材料未给出该方案与静态 INT8、FP8、NVFP4 的对比，因此量化方案选择依据本身是不完整的，迁移时不能默认动态 INT8 是最优解。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Efficient Audio-Visual </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Event Recognitio…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Efficient Audio-Visual … 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称与规模</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出准确率、延迟、显存占用与吞吐数字；仅可确认论文报告了蒸馏加动态 …</td></tr><tr><td>消融</td><td>材料未给出消融实验细节；从机制上可推断的消融维度包括蒸馏损失各项权重、是否…</td></tr><tr><td>局限</td><td>材料未给出量化后精度损失幅度、跨注意力层对量化的敏感度、以及不同硬件档位上…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-efficient-audio-visual-event-recogni-2026 · 共 9 个片段</p>\n";break;}}})();
